/* oxlint-disable anti-slop/no-known-value-widening -- Lookup tables and parse results are typed by their string keys. */
/* oxlint-disable shadcn/no-inline-styles -- The component styles each span from its SGR codes and each line number inline. */

import { parseAnsi } from "@/components/markdown/ansi";
import type { AnsiSpan } from "@/components/markdown/ansi";
import { cn } from "@/lib/utils";
import type { CSSProperties } from "react";

/**
 * Colors of the `.ansi-*-fg` and `.ansi-*-bg` rules. Each is
 * `!important` and takes the Electron terminal token, which resolves to the
 * app foreground colors and the red, green, yellow, blue and purple accents.
 * The stylesheet defines the 8 normal colors for both, the 8 bright colors for
 * the foreground only, and nothing for 256-color palette entries, truecolor or
 * bright backgrounds; those classes are kept on the span and stay unstyled.
 */
const FOREGROUND: Record<string, string> = {
  "ansi-black": "text-(--ck-fixed-black)!",
  "ansi-blue": "text-(--ck-palette-accent-blue)!",
  "ansi-bright-black": "text-text-muted!",
  "ansi-bright-blue": "text-(--ck-palette-accent-blue)!",
  "ansi-bright-cyan": "text-(--ck-palette-accent-blue)!",
  "ansi-bright-green": "text-[var(--color-status-success)]!",
  "ansi-bright-magenta": "text-(--ck-palette-accent-purple)!",
  "ansi-bright-red": "text-[var(--color-status-danger)]!",
  "ansi-bright-white": "text-text!",
  "ansi-bright-yellow": "text-[var(--color-status-caution)]!",
  "ansi-cyan": "text-(--ck-palette-accent-blue)!",
  "ansi-green": "text-[var(--color-status-success)]!",
  "ansi-magenta": "text-(--ck-palette-accent-purple)!",
  "ansi-red": "text-[var(--color-status-danger)]!",
  "ansi-white": "text-(--ck-fixed-white)!",
  "ansi-yellow": "text-[var(--color-status-caution)]!",
};

const BACKGROUND: Record<string, string> = {
  "ansi-black": "bg-text-subtle!",
  "ansi-blue": "bg-(--ck-palette-accent-blue)!",
  "ansi-cyan": "bg-(--ck-palette-accent-blue)!",
  "ansi-green": "bg-[var(--color-status-success)]!",
  "ansi-magenta": "bg-(--ck-palette-accent-purple)!",
  "ansi-red": "bg-[var(--color-status-danger-solid)]!",
  "ansi-white": "bg-(--ck-fixed-white)!",
  "ansi-yellow": "bg-[var(--color-status-caution)]!",
};

/** The one decoration kept per span becomes inline style. */
const decorationStyle = (span: AnsiSpan): CSSProperties | undefined => {
  if (span.decoration === null) {
    return undefined;
  }

  switch (span.decoration) {
    case "bold": {
      return { fontWeight: "bold" };
    }

    case "dim": {
      return { opacity: "0.7" };
    }

    case "italic": {
      return { fontStyle: "italic" };
    }

    case "hidden": {
      return { visibility: "hidden" };
    }

    case "underline": {
      return { textDecorationLine: "underline" };
    }

    case "strikethrough": {
      return { textDecorationLine: "line-through" };
    }

    default: {
      return undefined;
    }
  }
};

export interface AnsiBlockProps {
  /** Terminal output with ANSI escape sequences. */
  children?: string | null;
  className?: string;
}

/**
 * Terminal output in a `<code>`.
 * Backspaces and carriage-return overwrites are applied, escape sequences are
 * stripped, and SGR color and decoration codes become classes and styles.
 */
export const AnsiBlock = ({ children, className }: AnsiBlockProps) => (
  <code className={className}>
    {parseAnsi(children).map((span, index) => (
      <span
        className={cn(
          span.fg !== null && `${span.fg}-fg`,
          span.bg !== null && `${span.bg}-bg`,
          span.fg !== null && FOREGROUND[span.fg],
          span.bg !== null && BACKGROUND[span.bg]
        )}
        // oxlint-disable-next-line react/no-array-index-key -- spans are positional output of one string.
        key={index}
        style={decorationStyle(span)}
      >
        {span.content}
      </span>
    ))}
  </code>
);

/* oxlint-disable anti-slop/no-known-value-widening -- Lookup tables and parse results are typed by their string keys. */
/* oxlint-disable eslint/complexity -- The parsers are single-pass state machines that follow the reference algorithms branch for branch. */
/* oxlint-disable eslint/prefer-named-capture-group -- The grammars are written with positional groups, as the reference parsers do. */
/* oxlint-disable eslint/require-unicode-regexp -- The patterns are CommonMark, GFM and ANSI grammar kept without the u flag, which rejects the escaped punctuation classes they use. */
/* oxlint-disable typescript/strict-boolean-expressions -- Branches test optional flags, regex groups and empty strings by truthiness, as react-markdown and the component do. */
/* oxlint-disable unicorn/prefer-code-point -- Stylistic; the code compares UTF-16 code units of the escape and BOM characters. */
/* oxlint-disable unicorn/prefer-number-coercion -- Stylistic; parseInt reads the leading digits of an escape parameter. */

/**
 * ANSI escape handling for the ANSI block.
 * Preprocessing (carriage-return overwrites, backspace removal) and the SGR
 * parsing of the `anser` library (MIT) in
 * its `ansiToJson({ use_classes: true, remove_empty: true })` mode.
 */

export interface AnsiSpan {
  bg: string | null;
  content: string;
  /** Only the last decoration is kept, as the span styles do. */
  decoration: string | null;
  fg: string | null;
}

const COLOR_CLASSES = [
  [
    "ansi-black",
    "ansi-red",
    "ansi-green",
    "ansi-yellow",
    "ansi-blue",
    "ansi-magenta",
    "ansi-cyan",
    "ansi-white",
  ],
  [
    "ansi-bright-black",
    "ansi-bright-red",
    "ansi-bright-green",
    "ansi-bright-yellow",
    "ansi-bright-blue",
    "ansi-bright-magenta",
    "ansi-bright-cyan",
    "ansi-bright-white",
  ],
] as const;

const ESC = String.fromCharCode(27);
const BACKSPACE = String.fromCharCode(8);
const ANY_ESCAPE = new RegExp(`${ESC}\\[[\\d;]*[A-Za-z]`, "g");
const SGR_ESCAPE = new RegExp(`${ESC}\\[[\\d;]*m`, "g");
const CLEAR_LINE = new RegExp(`${ESC}\\[(?:0|2)?K`);
const SPLIT_ESCAPE = new RegExp(`${ESC}\\[`);

const CHUNK =
  /^([!\u003C-\u003F]*)([\d;]*)([\u0020-\u002C]*[\u0040-\u007E])([\s\S]*)/m;

const BACKSPACE_PAIR = new RegExp(`[^\\n]${BACKSPACE}`, "gm");
const CRLF = /\r+\n/gm;
const OVERWRITE = /^([^\r\n]*)\r+([^\r\n]+)/gm;
const CARRIAGE_RETURN_TEXT = /\r./;

/** Removes `<char><backspace>` pairs until none are left. */
const applyBackspaces = (value: string): string => {
  let current = value;
  let next = current;

  do {
    current = next;
    next = current.replaceAll(BACKSPACE_PAIR, "");
  } while (next.length < current.length);

  return current;
};

/** Applies carriage-return overwrites line by line. */
const applyCarriageReturns = (value: string): string => {
  if (!value) {
    return "";
  }

  if (!value.includes("\r")) {
    return value;
  }

  let result = value.replaceAll(CRLF, "\n");

  while (CARRIAGE_RETURN_TEXT.test(result)) {
    result = result.replaceAll(
      OVERWRITE,
      (_whole, before: string, after: string) => {
        const visible = after.replaceAll(ANY_ESCAPE, "").length;
        const sgr = before.match(SGR_ESCAPE)?.join("") ?? "";
        let seen = 0;
        const clears = CLEAR_LINE.test(after);

        const kept = clears
          ? ""
          : before.replaceAll(
              new RegExp(`${ANY_ESCAPE.source}|.`, "g"),
              (piece) => {
                if (piece.startsWith(ESC)) {
                  return piece;
                }

                const keep = seen >= visible;
                seen += 1;

                return keep ? piece : "";
              }
            );

        return (
          sgr +
          after +
          (kept && SGR_ESCAPE.test(after) ? `${ESC}[0m` : "") +
          kept
        );
      }
    );
  }

  return result;
};

interface State {
  bg: string | null;
  decorations: string[];
  fg: string | null;
}

const removeDecoration = (state: State, name: string): void => {
  const at = state.decorations.indexOf(name);

  if (at !== -1) {
    state.decorations.splice(at, 1);
  }
};

const applyCode = (state: State, codes: string[], first: string): void => {
  const code = Number.parseInt(first, 10);

  if (Number.isNaN(code) || code === 0) {
    state.fg = null;
    state.bg = null;
    state.decorations = [];

    return;
  }

  const decorationOn: Record<number, string> = {
    1: "bold",
    2: "dim",
    3: "italic",
    4: "underline",
    5: "blink",
    7: "reverse",
    8: "hidden",
    9: "strikethrough",
  };

  const decorationOff: Record<number, string[]> = {
    21: ["bold"],
    22: ["bold", "dim"],
    23: ["italic"],
    24: ["underline"],
    25: ["blink"],
    27: ["reverse"],
    28: ["hidden"],
    29: ["strikethrough"],
  };

  const on = decorationOn[code];

  if (on) {
    state.decorations.push(on);

    return;
  }

  const off = decorationOff[code];

  if (off) {
    for (const name of off) {
      removeDecoration(state, name);
    }

    return;
  }

  if (code === 39) {
    state.fg = null;
  } else if (code === 49) {
    state.bg = null;
  } else if (code >= 30 && code < 38) {
    state.fg = COLOR_CLASSES[0][code % 10] ?? null;
  } else if (code >= 90 && code < 98) {
    state.fg = COLOR_CLASSES[1][code % 10] ?? null;
  } else if (code >= 40 && code < 48) {
    state.bg = COLOR_CLASSES[0][code % 10] ?? null;
  } else if (code >= 100 && code < 108) {
    state.bg = COLOR_CLASSES[1][code % 10] ?? null;
  } else if ((code === 38 || code === 48) && codes.length >= 1) {
    const foreground = code === 38;
    const mode = codes.shift();

    if (mode === "5" && codes.length >= 1) {
      const index = Number.parseInt(codes.shift() ?? "", 10);

      if (index >= 0 && index <= 255) {
        const name =
          index >= 16
            ? `ansi-palette-${index}`
            : (COLOR_CLASSES[Number(index > 7)][index % 8] ?? null);

        if (foreground) {
          state.fg = name;
        } else {
          state.bg = name;
        }
      }
    } else if (mode === "2" && codes.length >= 3) {
      const red = Number.parseInt(codes.shift() ?? "", 10);
      const green = Number.parseInt(codes.shift() ?? "", 10);
      const blue = Number.parseInt(codes.shift() ?? "", 10);
      const valid = [red, green, blue].every((v) => v >= 0 && v <= 255);

      if (valid) {
        if (foreground) {
          state.fg = "ansi-truecolor";
        } else {
          state.bg = "ansi-truecolor";
        }
      }
    }
  }
};

const processChunk = (chunk: string, state: State): AnsiSpan => {
  const result: AnsiSpan = {
    bg: null,
    content: chunk,
    decoration: null,
    fg: null,
  };

  const match = CHUNK.exec(chunk);

  if (!match) {
    return result;
  }

  result.content = match[4] ?? "";

  if ((match[1] ?? "") !== "" || match[3] !== "m") {
    return result;
  }

  const codes = (match[2] ?? "").split(";");

  while (codes.length > 0) {
    applyCode(state, codes, codes.shift() ?? "");
  }

  if (
    state.fg === null &&
    state.bg === null &&
    state.decorations.length === 0
  ) {
    return result;
  }

  let { fg, bg } = state;

  const decorations = state.decorations.filter((name) => {
    if (name === "reverse") {
      fg ??= COLOR_CLASSES[0][7];
      bg ??= COLOR_CLASSES[0][0];
      [fg, bg] = [bg, fg];

      return false;
    }

    return true;
  });

  result.fg = fg;
  result.bg = bg;
  result.decoration = decorations.at(-1) ?? null;

  return result;
};

/** The AnsiBlock data path: the spans for one terminal output. */
export const parseAnsi = (input: string | undefined | null): AnsiSpan[] => {
  const prepared = applyCarriageReturns(applyBackspaces(input ?? ""));
  const [lead = "", ...chunks] = prepared.split(SPLIT_ESCAPE);
  const state: State = { bg: null, decorations: [], fg: null };

  const spans: AnsiSpan[] = [
    { bg: null, content: lead, decoration: null, fg: null },
    ...chunks.map((chunk) => processChunk(chunk, state)),
  ];

  return spans.filter((span) => span.content !== "");
};

"use client";

/* oxlint-disable anti-slop/require-readable-spacing, eslint/complexity, eslint/no-nested-ternary, eslint/require-await, eslint/require-unicode-regexp -- The block follows the component branch for branch. */
/* oxlint-disable shadcn/no-restyle, shadcn/no-unknown-classes, typescript/promise-function-async, typescript/return-await -- The component styles these elements itself; the copy handler returns the clipboard promise. */

/* oxlint-disable anti-slop/no-known-value-widening -- Lookup tables are typed by their string keys. */
/* oxlint-disable anti-slop/no-runtime-typeof -- A value may be a string or a function, as in the components. */
/* oxlint-disable shadcn/no-arbitrary-values -- The classes are the calc values and surfaces; no theme token matches them. */
/* oxlint-disable typescript/consistent-return -- Effects return a cleanup only when they registered something. */
/* oxlint-disable typescript/strict-boolean-expressions -- Branches test optional flags by truthiness. */

import {
  ChatCodeIcon,
  ChatCodeWrapOffIcon,
  ChatCodeWrapOnIcon,
} from "@/components/markdown/chat-code-icons";
import { CopyActionButton } from "@/components/markdown/copy-action-button";
import { highlightLines } from "@/components/markdown/highlight-view";
import { Button } from "@/components/ui/button";
import { copyMarkdownText } from "@/components/ui/markdown";
import { TooltipHint } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { useEffect, useMemo, useRef, useState } from "react";
import type { ReactNode, RefObject } from "react";

/**
 * The full code block of the chat prose: the block, the visibility swap, the
 * chrome, the action bar, the code and its deferral, the copy button, the
 * language labels and the svg test, with their surfaces.
 */

// ---- language labels -------------------------------------------

const LANGUAGES: readonly (readonly [value: string, label: string | null])[] = [
  ["arduino", "Arduino"],
  ["bash", "Bash"],
  ["c", "C"],
  ["cpp", "C++"],
  ["csharp", "C#"],
  ["css", "CSS"],
  ["diff", "Diff"],
  ["go", "Go"],
  ["graphql", "GraphQL"],
  ["ini", "INI"],
  ["java", "Java"],
  ["javascript", "JavaScript"],
  ["json", "JSON"],
  ["kotlin", "Kotlin"],
  ["latex", "LaTeX"],
  ["less", "Less"],
  ["lua", "Lua"],
  ["makefile", "Makefile"],
  ["markdown", "Markdown"],
  ["mermaid", "Mermaid"],
  ["objectivec", "Objective-C"],
  ["perl", "Perl"],
  ["php", "PHP"],
  ["php-template", "PHP template"],
  ["plaintext", null],
  ["python", "Python"],
  ["python-repl", "Python REPL"],
  ["r", "R"],
  ["ruby", "Ruby"],
  ["rust", "Rust"],
  ["scss", "SCSS"],
  ["shell", "Shell"],
  ["sql", "SQL"],
  ["swift", "Swift"],
  ["typescript", "TypeScript"],
  ["vbnet", "Visual Basic .NET"],
  ["wasm", "WebAssembly"],
  ["xml", "XML"],
  ["yaml", "YAML"],
];

const LANGUAGE_ALIASES: Record<string, string> = {
  "c#": "csharp",
  "c++": "cpp",
  cs: "csharp",
  gql: "graphql",
  html: "xml",
  js: "javascript",
  jsx: "javascript",
  math: "latex",
  md: "markdown",
  objc: "objectivec",
  patch: "diff",
  py: "python",
  rb: "ruby",
  rs: "rust",
  sh: "bash",
  tex: "latex",
  text: "plaintext",
  ts: "typescript",
  tsx: "typescript",
  vb: "vbnet",
  yml: "yaml",
  zsh: "bash",
};

const LABELS = new Map(LANGUAGES);

const PLAIN_TEXT_LABEL = "Plain text";

/** The display label of a fence language, or undefined when it is not a known language. */
export const codeLanguageLabel = (language: string): string | undefined => {
  const key = language.trim().toLowerCase();
  const value = LABELS.has(key) ? key : LANGUAGE_ALIASES[key];

  if (value === undefined || !LABELS.has(value)) {
    return;
  }

  return LABELS.get(value) ?? PLAIN_TEXT_LABEL;
};

/** An svg source (the fence language `svg`, or xml and html that start with `<svg`). */
export const isSvgCodeBlock = (code: string, language?: string): boolean =>
  language === "svg" ||
  ((language === "xml" || language === "html") && /^\s*<svg/.test(code));

// Visibility.

/**
 * False until the element is within 600px of the viewport, then
 * true for good. Without `deferred` it is true at once. Without
 * IntersectionObserver it turns true on the next tick.
 */
export const useVisibleOnce = (
  ref: RefObject<Element | null>,
  deferred: boolean
): boolean => {
  const [seen, setSeen] = useState(false);
  const visible = !deferred || seen;

  useEffect(() => {
    if (visible) {
      return;
    }

    const element = ref.current;

    if (element === null) {
      return;
    }

    if (typeof IntersectionObserver === "undefined") {
      const timer = setTimeout(() => {
        setSeen(true);
      }, 0);

      return () => {
        clearTimeout(timer);
      };
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setSeen(true);
          observer.disconnect();
        }
      },
      { rootMargin: "640px 0px" }
    );

    observer.observe(element);

    return () => {
      observer.disconnect();
    };
  }, [ref, visible]);

  return visible;
};

export interface DeferUntilVisibleProps {
  /** Shown until the block is near the viewport. */
  fallback: ReactNode;
  /** Renders the block at once. */
  renderImmediately?: boolean;
  renderVisible: () => ReactNode;
}

/** The fallback sits in a div until it is near the viewport, then the block replaces it. */
export const DeferUntilVisible = ({
  fallback,
  renderImmediately = false,
  renderVisible,
}: DeferUntilVisibleProps) => {
  const ref = useRef<HTMLDivElement>(null);
  const visible = useVisibleOnce(ref, !renderImmediately);

  return visible ? renderVisible() : <div ref={ref}>{fallback}</div>;
};

// The code block.

export interface MarkdownProseCodeBlockProps {
  /** The code, without the trailing newline. */
  code: string;
  className?: string;
  /** Label of the copy button. Default "Copy code". */
  copyLabel?: string;
  /** Word wrap is on and cannot be turned off. */
  forceWordWrap?: boolean;
  /** The fence is still open while the text streams: no copy button, title may be empty. */
  isCodeFenceOpen?: boolean;
  /** The fence info string. */
  language?: string;
  /** The header stays under the thread header while the block scrolls. */
  stickyHeader?: boolean;
  /** Labels of the word wrap button. Defaults "Enable word wrap" and "Disable word wrap". */
  wrapLabels?: { disable: string; enable: string };
}

const DEFAULT_WRAP_LABELS = {
  disable: "Disable word wrap",
  enable: "Enable word wrap",
};

const SURFACE =
  "[corner-shape:superellipse(1.1)] bg-panel bg-[image:linear-gradient(var(--ck-palette-surface-button-secondary-hover),var(--ck-palette-surface-button-secondary-hover))]";

const STICKY_BAR =
  "sticky top-[calc(-1px-var(--ck-chat-sticky-header-top,0px))] z-10 bg-panel bg-[image:linear-gradient(var(--ck-palette-surface-button-secondary-hover),var(--ck-palette-surface-button-secondary-hover))]";

/** Prism token types mapped to the highlight.js colours. */
const SYNTAX_CLASSES: Record<string, string> = {
  "attr-name": "text-syntax-attribute",
  boolean: "text-syntax-literal",
  builtin: "text-syntax-literal",
  "class-name": "text-syntax-variable",
  comment: "text-syntax-comment italic",
  constant: "text-syntax-literal",
  function: "text-syntax-variable",
  keyword: "text-syntax-keyword",
  number: "text-syntax-literal",
  operator: "text-syntax-keyword",
  regex: "text-syntax-string",
  string: "text-syntax-string",
  "template-string": "text-syntax-string",
};

/** The last class with a colour wins, as Prism lists the type before its aliases. */
const syntaxClassName = (classes: readonly string[]): string => {
  const colour = classes.findLast((name) => name in SYNTAX_CLASSES);

  return cn(classes, colour === undefined ? undefined : SYNTAX_CLASSES[colour]);
};

const CODE_CLASSES =
  "block font-mono text-[length:var(--ui-code-text-size,12px)] leading-[max(1.5em,calc(var(--spacing)*5))]";

/**
 * A normal block. The action bar holds the language title (with the code
 * glyph), the word wrap toggle and the copy button; the code sits under it in a scrolling, focusable container. Token colouring is
 * deferred until the block is near the viewport. Refractor tokenizes it and the tokens
 * take the highlight.js colours.
 */
export const MarkdownProseCodeBlock = ({
  className,
  code,
  copyLabel = "Copy code",
  forceWordWrap = false,
  isCodeFenceOpen = false,
  language,
  stickyHeader = false,
  wrapLabels = DEFAULT_WRAP_LABELS,
}: MarkdownProseCodeBlockProps) => {
  const [userWrap, setUserWrap] = useState(false);
  const sourceRef = useRef<HTMLDivElement>(null);
  const enhanced = useVisibleOnce(sourceRef, true);
  const svg = isSvgCodeBlock(code, language);
  const wrapMode = svg ? "off" : forceWordWrap ? "always" : "user-controlled";
  const wrapped =
    wrapMode === "always" || (wrapMode === "user-controlled" && userWrap);
  const known =
    language === undefined ? undefined : codeLanguageLabel(language);
  const title = known ?? language ?? (isCodeFenceOpen ? "" : undefined);
  const wrapLabel = wrapped ? wrapLabels.disable : wrapLabels.enable;
  const content = useMemo(
    () =>
      enhanced && !svg && language !== undefined
        ? highlightLines(code, language, false, syntaxClassName)
        : code,
    [code, enhanced, language, svg]
  );

  return (
    <div
      className={cn(
        "relative w-full min-w-0 overflow-clip rounded-3xl border border-stroke-subtle text-text contain-inline-size",
        SURFACE,
        className
      )}
      data-code-block
      data-enhanced={enhanced ? "" : undefined}
      data-ck-markdown-copy="code-block"
    >
      <div
        className={cn(
          "flex min-h-12 items-center gap-2 py-1.5 ps-4 pe-1.5 font-sans text-sm font-medium text-text select-none md:ps-5 print:hidden",
          stickyHeader && STICKY_BAR
        )}
        contentEditable={false}
        data-ck-markdown-copy="exclude"
      >
        {title === undefined ? null : (
          <ChatCodeIcon className="size-4 shrink-0" />
        )}
        <div className="min-w-0 flex-1 truncate">{title}</div>
        <div className="ms-auto flex max-w-full min-w-0 items-center">
          <div
            className="flex flex-wrap items-center justify-end gap-px"
            data-code-block-controls
            role="presentation"
          >
            {wrapMode === "user-controlled" ? (
              <TooltipHint cloneCustomTrigger content={wrapLabel}>
                <Button
                  aria-label={wrapLabel}
                  aria-pressed={wrapped}
                  className={wrapped ? "hover:text-text" : undefined}
                  color="ghostActive"
                  onClick={() => {
                    setUserWrap((value) => !value);
                  }}
                  size="imageToolbar"
                  uniform
                >
                  {wrapped ? (
                    <ChatCodeWrapOnIcon className="size-3.5" />
                  ) : (
                    <ChatCodeWrapOffIcon className="size-3.5" />
                  )}
                </Button>
              </TooltipHint>
            ) : null}
            {isCodeFenceOpen ? null : (
              <CopyActionButton
                label={copyLabel}
                onCopy={async () => copyMarkdownText(code)}
                variant="toolbar"
              />
            )}
          </div>
        </div>
      </div>
      <div
        className={cn(
          "overflow-auto px-4 pt-0 pb-3 text-[length:var(--ui-message-text-size,13px)] outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset md:px-5",
          wrapped ? "wrap-anywhere whitespace-pre-wrap" : "whitespace-pre"
        )}
        data-code-block-source
        dir="ltr"
        ref={sourceRef}
      >
        <pre className="whitespace-[inherit] m-0 border-0 bg-transparent p-0">
          <code
            className={cn(
              CODE_CLASSES,
              wrapped ? "whitespace-pre-wrap!" : "whitespace-pre!"
            )}
