// ---- component ----------------------------------------------------------------

export interface CodeEditorHandle {
  focus: () => void;
}

export interface CodeEditorProps {
  autoFocus?: boolean;
  className?: string;
  code: string;
  /** The `aria-label` of the editing surface. Default `Edit code`. */
  label?: string;
  /**
   * Language name. `latex` and `tex` select the LaTeX highlighting, and a name
   * with a mode (bash, zsh) its own. Any other name is a plain editor.
   */
  language?: string;
  messages?: CodeEditorFindMessages;
  onBlur?: (event: FocusEvent) => void;
  onChange?: (code: string) => void;
  placeholder?: string;
  ref?: Ref<CodeEditorHandle>;
  wrapLines?: boolean;
}

const buildExtensions = (
  messages: CodeEditorFindMessages,
  compartments: Record<
    "a11y" | "language" | "placeholder" | "wrapping",
    Compartment
  >,
  options: {
    label: string;
    language?: string;
    placeholder?: string;
    wrapLines: boolean;
  },
  listeners: Extension
): Extension[] => [
  compartments.language.of(languageExtension(options.language)),
  editorTheme,
  highlightStyle,
  compartments.wrapping.of(
    isLatex(options.language) || options.wrapLines
      ? EditorView.lineWrapping
      : []
  ),
  compartments.placeholder.of(
    options.placeholder === undefined
      ? []
      : placeholderExtension(options.placeholder)
  ),
  compartments.a11y.of(
    EditorView.contentAttributes.of({
      "aria-label": options.label,
      "aria-multiline": "true",
      spellcheck: "false",
    })
  ),
  search({ createPanel: createFindPanel(messages), top: true }),
  panelTheme,
  history(),
  codeFolding(),
  autocompletion(),
  keymap.of(editorKeymaps.flat()),
  listeners,
];

/** An editable code block backed by CodeMirror. */
export const CodeEditor = ({
  autoFocus = true,
  className,
  code,
  label = DEFAULT_EDITOR_LABEL,
  language,
  messages = DEFAULT_FIND_MESSAGES,
  onBlur,
  onChange,
  placeholder,
  ref,
  wrapLines = false,
}: CodeEditorProps) => {
  const parent = useRef<HTMLDivElement>(null);
  const view = useRef<EditorView | null>(null);

  const compartments = useRef({
    a11y: new Compartment(),
    language: new Compartment(),
    placeholder: new Compartment(),
    wrapping: new Compartment(),
  });

  const emitChange = useEffectEvent((value: string) => onChange?.(value));
  const emitBlur = useEffectEvent((event: FocusEvent) => onBlur?.(event));

  useImperativeHandle(ref, () => ({ focus: () => view.current?.focus() }));

  const latex = isLatex(language);

  const create = useEffectEvent((element: HTMLElement) => {
    const editor = new EditorView({
      parent: element,
      state: EditorState.create({
        doc: code,
        extensions: buildExtensions(
          messages,
          compartments.current,
          { label, language, placeholder, wrapLines },
          [
            EditorView.updateListener.of((update) => {
              if (
                update.transactions.some(
                  (transaction) =>
                    transaction.docChanged && !transaction.annotation(external)
                )
              ) {
                emitChange(update.state.doc.toString());
              }
            }),
            EditorView.domEventHandlers({
              blur: (event) => {
                emitBlur(event);
              },
            }),
          ]
        ),
      }),
    });

    editor.scrollDOM.classList.add("code-scrollport");
    view.current = editor;

    if (autoFocus) {
      editor.focus();
    }

    return () => {
      view.current = null;
      editor.destroy();
    };
  });

  useEffect(() => {
    if (parent.current) {
      return create(parent.current);
    }
  }, []);

  useEffect(() => {
    view.current?.dispatch({
      effects: compartments.current.language.reconfigure(
        languageExtension(language)
      ),
    });
  }, [language]);

  useEffect(() => {
    view.current?.dispatch({
      effects: [
        compartments.current.wrapping.reconfigure(
          latex || wrapLines ? EditorView.lineWrapping : []
        ),
        compartments.current.placeholder.reconfigure(
          placeholder === undefined ? [] : placeholderExtension(placeholder)
        ),
        compartments.current.a11y.reconfigure(
          EditorView.contentAttributes.of({
            "aria-label": label,
            "aria-multiline": "true",
            spellcheck: "false",
          })
        ),
      ],
    });
  }, [label, latex, placeholder, wrapLines]);

  useEffect(() => {
    const editor = view.current;

    if (editor && editor.state.doc.toString() !== code) {
      editor.dispatch({
        annotations: [external.of(true), Transaction.addToHistory.of(false)],
        changes: { from: 0, insert: code, to: editor.state.doc.length },
      });
    }
  }, [code]);

  return (
    <div
      className={cn(
        "min-h-24 w-full overflow-auto text-(length:--text-code,0.875em)",
        latex && "h-full",
        className
      )}
      data-ck-editor-search-surface
      dir="ltr"
      onCopy={(event) => {
        if (
          event.target instanceof Element &&
          event.target.closest(".cm-editor")
        ) {
          event.stopPropagation();
        }
      }}
      ref={parent}
    />
  );
};

"use client";

/* oxlint-disable promise/always-return, promise/catch-or-return, promise/prefer-catch, typescript/no-invalid-void-type -- The handler may return nothing or a promise of the result, as the onCopy does. */

/* oxlint-disable typescript/consistent-return -- Effects return a cleanup only when they registered something. */
/* oxlint-disable typescript/strict-boolean-expressions -- Branches test optional flags by truthiness. */

import {
  ChatCodeCheckIcon,
  ChatCodeCopyIcon,
} from "@/components/markdown/chat-code-icons";
import { Button } from "@/components/ui/button";
import { TooltipHint } from "@/components/ui/tooltip";
import { useEffect, useRef, useState } from "react";
import type { KeyboardEventHandler, MouseEvent } from "react";

const COPIED_RESET_MS = 2000;

const VARIANT_PROPS = {
  blockAction: { color: "blockAction", radius: "full", size: "inputIcon" },
  messageAction: { color: "ghost", size: "icon" },
  toolbar: { color: "ghostActive", size: "imageToolbar", uniform: true },
} as const;

export interface CopyActionButtonProps {
  /** Accessible label and tooltip. Pressed state reads "Copied". */
  label: string;
  /**
   * Runs the copy. A promise keeps the button busy until it settles. A result
   * of `false` (or a rejection) shows no check mark.
   */
  onCopy: (
    event: MouseEvent<HTMLButtonElement>
  ) => boolean | Promise<boolean> | undefined | void;
  onKeyDown?: KeyboardEventHandler<HTMLButtonElement>;
  /**
   * `toolbar` is a ghost image-toolbar button, `blockAction` a round block action,
   * `messageAction` the 26px ghost button under a chat message.
   */
  variant: "blockAction" | "messageAction" | "toolbar";
}

/**
 * The copy button as an icon-only button: the click stops
 * propagation, ignores presses while busy or while "Copied" shows, marks the
 * button `aria-busy` while a promise runs and swaps the glyph for a check for
 * two seconds after a successful copy.
 */
export const CopyActionButton = ({
  label,
  onCopy,
  onKeyDown,
  variant,
}: CopyActionButtonProps) => {
  const [copied, setCopied] = useState(false);
  const [busy, setBusy] = useState(false);
  const pending = useRef(false);
  const timer = useRef<number | undefined>(undefined);

  useEffect(
    () => () => {
      window.clearTimeout(timer.current);
    },
    []
  );

  const settle = (ok: boolean) => {
    pending.current = false;
    setBusy(false);

    if (ok) {
      setCopied(true);
      window.clearTimeout(timer.current);
      timer.current = window.setTimeout(() => {
        timer.current = undefined;
        setCopied(false);
      }, COPIED_RESET_MS);
    }
  };

  const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
    event.stopPropagation();

    if (pending.current || copied) {
      return;
    }

    const result = onCopy(event);

    if (result instanceof Promise) {
      pending.current = true;
      setBusy(true);
      result.then(
        (ok) => {
          settle(ok);
        },
        () => {
          settle(false);
        }
      );
    } else {
      settle(result !== false);
    }
  };

  const ariaLabel = copied ? "Copied" : label;
  const Icon = copied ? ChatCodeCheckIcon : ChatCodeCopyIcon;

  return (
    <TooltipHint cloneCustomTrigger content={ariaLabel}>
      <Button
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        aria-label={ariaLabel}
        {...VARIANT_PROPS[variant]}
        onClick={handleClick}
        onKeyDown={onKeyDown}
      >
        <Icon className={variant === "messageAction" ? "icon-xs" : "size-4"} />
      </Button>
    </TooltipHint>
  );
};

/* oxlint-disable anti-slop/no-array-filter-map, eslint/no-unused-vars, eslint/no-use-before-define -- The serializer functions call each other recursively, as the do. */
/* oxlint-disable unicorn/no-useless-spread, unicorn/prefer-dom-node-dataset, unicorn/prefer-ternary -- The spreads copy live NodeLists; attributes are read with getAttribute because the nodes are Element, not HTMLElement. */
/* oxlint-disable anti-slop/no-known-value-widening -- Lookup tables are typed by their string keys. */
/* oxlint-disable eslint/complexity -- The serializer follows the branch for branch. */
/* oxlint-disable eslint/prefer-destructuring -- Stylistic. */
/* oxlint-disable typescript/prefer-nullish-coalescing, typescript/strict-boolean-expressions -- Branches test optional values by truthiness. */
/* oxlint-disable unicorn/no-array-for-each, unicorn/prefer-dom-node-append -- Stylistic; the calls stay as written. */

/**
 * The selection and element serializer of the chat prose: the selection, the
 * element, the copy event, rich HTML, plain text and the HTML string.
 *
 * KaTeX and math source, inline visualizations, `data-ck-d-component` images and
 * host inline mentions are not handled, because the library renders none of
 * them.
 */

const COPY_ATTRIBUTE = "data-ck-markdown-copy";
const CONTENT_ATTRIBUTE = "data-markdown-copy-content";
const TEXT_ATTRIBUTE = "data-markdown-copy-text";
const COPY_SELECTOR = `[${COPY_ATTRIBUTE}]`;
const CONTENT_SELECTOR = `[${CONTENT_ATTRIBUTE}]`;

const EDITABLE_SELECTOR =
  '[contenteditable="true"], [contenteditable="plaintext-only"]';

const XHTML_NAMESPACE = "http://www.w3.org/1999/xhtml";

const BLOCK_TAGS = new Set([
  "BLOCKQUOTE",
  "DIV",
  "H1",
  "H2",
  "H3",
  "H4",
  "H5",
  "H6",
  "LI",
  "P",
  "PRE",
]);

// Attributes the rich html keeps, by tag.
const KEPT_ATTRIBUTES: Record<string, string[]> = {
  A: ["href", "title"],
  BLOCKQUOTE: ["cite"],
  CODE: ["data-language", TEXT_ATTRIBUTE],
  IMG: ["src", "srcset", "sizes", "alt", "title", "width", "height"],
  LI: ["value"],
  OL: ["start"],
  Q: ["cite"],
  TD: ["colspan", "rowspan"],
  TH: ["colspan", "rowspan"],
  TIME: ["datetime"],
};

export interface SerializedCopy {
  htmlText: string;
  plainText: string;
}

type CopyMode =
  | "blank-lines"
  | "code-block"
  | "contents"
  | "exclude"
  | "inline-code"
  | "rich-block";

const closestElement = (node: Node, selector: string): Element | null =>
  (node instanceof Element ? node : node.parentElement)?.closest(selector) ??
  null;

const copyMode = (element: Element | null): CopyMode | null => {
  const value = element?.getAttribute(COPY_ATTRIBUTE);

  return value === "exclude" ||
    value === "contents" ||
    value === "inline-code" ||
    value === "code-block" ||
    value === "rich-block" ||
    value === "blank-lines"
    ? value
    : null;
};

const rangeInside = (range: Range, root: Element): boolean =>
  root.contains(range.startContainer) && root.contains(range.endContainer);

/** Widens the range to take a whole matching ancestor. */
const widenRange = (range: Range, selector: string) => {
  const start = closestElement(range.startContainer, selector);

  if (start !== null) {
    range.setStartBefore(start);
  }

  const end = closestElement(range.endContainer, selector);

  if (end !== null) {
    range.setEndAfter(end);
  }
};

/** The marked element that holds both ends of the range. */
const markedAncestor = (range: Range, root: Element): Element | null => {
  const start = closestElement(range.startContainer, COPY_SELECTOR);
  const end = closestElement(range.endContainer, COPY_SELECTOR);

  return start !== null && start === end && root.contains(start) ? start : null;
};

/** A newline in preformatted text becomes a `<br>` in the clone. */
const breakNewlines = (range: Range, fragment: DocumentFragment) => {
  const original = document.createNodeIterator(
    range.commonAncestorContainer,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode: (node) =>
        range.intersectsNode(node)
          ? NodeFilter.FILTER_ACCEPT
          : NodeFilter.FILTER_REJECT,
    }
  );

  const cloned = document.createNodeIterator(fragment, NodeFilter.SHOW_TEXT);
  const replacements = new Map<Node, string[]>();

  for (let node = cloned.nextNode(); node !== null; node = cloned.nextNode()) {
    const parent = original.nextNode()?.parentElement;
    const value = node.nodeValue;

    if (
      parent !== null &&
      parent !== undefined &&
      value !== null &&
      value.includes("\n") &&
      parent.closest(
        `pre, [data-ck-markdown-copy="code-block"], [data-ck-markdown-copy="inline-code"], [data-ck-markdown-copy="blank-lines"]`
      ) === null &&
      ["pre", "pre-wrap", "pre-line", "break-spaces"].includes(
        window.getComputedStyle(parent).whiteSpace
      )
    ) {
      replacements.set(node, value.split("\n"));
    }
  }

  for (const [node, parts] of replacements) {
    const replacement = document.createDocumentFragment();
    parts.forEach((part, index) => {
      if (index > 0) {
        replacement.append(document.createElement("br"));
      }

      replacement.append(part);
    });
    node.parentNode?.replaceChild(replacement, node);
  }
};

const cloneRange = (range: Range): DocumentFragment => {
  const contents = range.cloneContents();
  breakNewlines(range, contents);

  return contents;
};

/** A preformatted block with the text as its code. */
const preformatted = (document_: Document, value: string): HTMLPreElement => {
  const pre = document_.createElement("pre");
  pre.dir = "ltr";
  const code = document_.createElement("code");
  code.textContent = value;
  pre.append(code);

  return pre;
};

/** The text of an element, preferring `data-markdown-copy-text`. */
const copyText = (node: Node): string => {
  if (node.nodeType === Node.TEXT_NODE) {
    return node.textContent ?? "";
  }

  if (node instanceof Element) {
    return (
      node.getAttribute(TEXT_ATTRIBUTE) ??
      (copyMode(node) === "exclude"
        ? ""
        : [...node.childNodes].map(copyText).join(""))
    );
  }

  return "";
};

const skipped = (element: Element): boolean =>
  element.classList.contains("sr-only") ||
  element.getAttribute("aria-hidden") === "true" ||
  (element.tagName === "IMG" && element.getAttribute("alt") === "");

// Rich HTML.

const appendRich = (parent: Node, node: Node, document_: Document) => {
  if (node.nodeType === Node.TEXT_NODE) {
    parent.appendChild(document_.createTextNode(node.textContent ?? ""));

    return;
  }

  if (!(node instanceof Element) || skipped(node)) {
    return;
  }

  const mode = copyMode(node);

  if (mode === "exclude") {
    return;
  }

  if (mode === "contents") {
    for (const child of [...node.childNodes]) {
      appendRich(parent, child, document_);
    }

    return;
  }

  if (mode === "blank-lines") {
    for (let index = 0; index < (node.textContent?.length ?? 0); index += 1) {
      parent.appendChild(document_.createElement("p"));
    }

    return;
  }

  if (node.matches('[role="checkbox"]')) {
    const input = document_.createElement("input");
    input.type = "checkbox";
    input.disabled = true;

    if (node.getAttribute("aria-checked") === "true") {
      input.setAttribute("checked", "");
    }

    parent.appendChild(input);

    return;
  }

  if (node.matches("button, [data-file-reference]")) {
    // A button with no mention inside is its copy text; otherwise its children.
    parent.appendChild(
      document_.createTextNode(
        node.getAttribute(TEXT_ATTRIBUTE) ?? node.textContent ?? ""
      )
    );

    return;
  }

  if (mode === "code-block") {
    const content = node.querySelector(`code${CONTENT_SELECTOR}`);

    if (content !== null) {
      const pre = document_.createElement("pre");
      pre.dir = "ltr";
      appendRich(pre, content, document_);
      parent.appendChild(pre);

      return;
    }

    parent.appendChild(preformatted(document_, copyText(node)));

    return;
  }

  if (mode === "rich-block") {
    const content = node.querySelector(CONTENT_SELECTOR);

    if (content !== null) {
      appendRich(parent, content, document_);
    }

    return;
  }

  if (mode === "inline-code") {
    const code = document_.createElement("code");
    code.dir = "ltr";

    for (const child of [...node.childNodes]) {
      appendRich(code, child, document_);
    }

    parent.appendChild(code);

    return;
  }

  if (node.namespaceURI !== XHTML_NAMESPACE) {
    // Foreign content (svg) keeps only its text.
    const value = node.textContent;

    if (value !== null && value.length > 0) {
      parent.appendChild(document_.createTextNode(value));
    }

    return;
  }

  const copy = document_.createElement(node.localName);

  for (const name of KEPT_ATTRIBUTES[node.tagName] ?? []) {
    const value = node.getAttribute(name);

    if (value !== null) {
      copy.setAttribute(name, value);
    }
  }

  for (const child of [...node.childNodes]) {
    appendRich(copy, child, document_);
  }

  parent.appendChild(copy);
};

const richFragment = (root: Node): DocumentFragment => {
  const document_ = root.ownerDocument ?? document;
  const fragment = document_.createDocumentFragment();

  for (const child of [...root.childNodes]) {
    appendRich(fragment, child, document_);
  }

  return fragment;
};

/** The html string, without the code text markers. */
const htmlOf = (fragment: DocumentFragment): string => {
  const holder = (fragment.ownerDocument ?? document).createElement("div");
  holder.append(fragment.cloneNode(true));

  for (const code of holder.querySelectorAll(`code[${TEXT_ATTRIBUTE}]`)) {
    code.removeAttribute(TEXT_ATTRIBUTE);
  }

  return holder.innerHTML;
};

// Plain text.

interface PlainState {
  end: number;
  nextRowOffset: number | null;
  start: number | null;
}

/** Records the span of the text that belongs to the selection. */
const mark = (
  value: string,
  state: PlainState | undefined,
  offset: number
): string => {
  if (state !== undefined && value.length > 0) {
    state.start ??= offset;
    state.end = offset + value.length;
  }

  return value;
};

const plainChildren = (
  nodes: Iterable<Node>,
  state?: PlainState,
  offset = 0
): string => {
  let result = "";

  for (const node of nodes) {
    result += plainNode(node, state, offset + result.length);
  }

  return result;
};

const rowText = (row: Element): string =>
  [...row.children]
    .filter((cell) => cell.tagName === "TH" || cell.tagName === "TD")
    .map((cell) => plainChildren(cell.childNodes).trim())
    .join("\t");

const listText = (list: Element, indent: string): string => {
  const ordered = list.tagName === "OL";
  const items = [...list.children].filter((child) => child.tagName === "LI");
  let counter = list instanceof HTMLOListElement ? list.start : 1;
  let result = "";

  for (const item of items) {
    if (
      ordered &&
      item instanceof HTMLLIElement &&
      item.hasAttribute("value")
    ) {
      counter = item.value;
    }

    const marker = ordered ? `${counter}. ` : "- ";
    counter += ordered ? 1 : 0;
    result += itemText(item, indent, marker);
  }

  return result;
};

const itemText = (item: Element, indent: string, marker: string): string => {
  const continuation = indent + " ".repeat(marker.length);
  let started = false;
  let buffer = "";
  let result = "";

  const flush = () => {
    const lines = buffer.trim().split("\n");
    buffer = "";

    if (lines.length !== 1 || lines[0] !== "") {
      for (const line of lines) {
        result += `${started ? continuation : indent + marker}${line}\n`;
        started = true;
      }
    }
  };

  for (const child of item.childNodes) {
    if (
      child instanceof Element &&
      (child.tagName === "OL" || child.tagName === "UL")
    ) {
      flush();

      if (!started) {
        result += `${indent}${marker.trimEnd()}\n`;
        started = true;
      }

      result += listText(child, continuation);
    } else {
      buffer += plainNode(child);
    }
  }

  flush();

  return started ? result : `${indent}${marker.trimEnd()}\n`;
};

const plainNode = (node: Node, state?: PlainState, offset = 0): string => {
  if (node.nodeType === Node.TEXT_NODE) {
    return node.textContent ?? "";
  }

  if (!(node instanceof Element)) {
    return "";
  }

  switch (node.tagName) {
    case "INPUT": {
      return node.getAttribute("type") === "checkbox"
        ? `[${node.hasAttribute("checked") ? "x" : " "}] `
        : "";
    }

    case "TABLE": {
      return mark(
        [...node.querySelectorAll("tr")].map(rowText).join("\n"),
        state,
        offset
      );
    }

    case "TR": {
      const row = rowText(node);

      if (state !== undefined) {
        if (state.nextRowOffset === offset) {
          mark("\n", state, offset - 1);
        }

        state.nextRowOffset = offset + row.length + 1;
      }

      return `${mark(row, state, offset)}\n`;
    }

    case "TD":
    case "TH": {
      const cell = plainChildren(node.childNodes).trim();

      if (node.nextElementSibling?.matches("td, th")) {
        mark("\t", state, offset + cell.length);
      }

      return `${cell}\t`;
    }

    case "THEAD":
    case "TBODY":
    case "TFOOT": {
      return plainChildren(node.children, state, offset);
    }

    case "BR": {
      return "\n";
    }

    case "P": {
      const previous = node.previousElementSibling;

      const gap =
        previous?.tagName === "P" &&
        previous.textContent?.trim() &&
        node.textContent?.trim() &&
        node.parentElement?.tagName !== "LI"
          ? "\n"
          : "";

      return `${gap}${plainChildren(node.childNodes, state, offset + gap.length)}\n`;
    }

    case "OL":
    case "UL": {
      return listText(node, "");
    }

    default: {
      const value = plainChildren(node.childNodes, state, offset);

      return BLOCK_TAGS.has(node.tagName) ||
        node.getAttribute("data-ck-math-display") === "true"
        ? `${value}\n`
        : value;
    }
  }
};

/** Trims the text to the span the selection covers. */
const plainText = (root: Node): string => {
  const state: PlainState = { end: 0, nextRowOffset: null, start: null };
  const value = plainChildren(root.childNodes, state);

  return state.start === null
    ? value.trim()
    : value.slice(0, state.start).trimStart() +
        value.slice(state.start, state.end) +
        value.slice(state.end).trimEnd();
};

const plainOf = (fragment: DocumentFragment, range: Range): string => {
  let value = plainText(fragment);

  const first = closestElement(
    range.startContainer,
    '[data-ck-markdown-copy="blank-lines"]'
  );

  if (first !== null) {
    const before = range.cloneRange();
    before.setEndAfter(first);
    value = before.toString() + value;
  }

  const last = closestElement(
    range.endContainer,
    '[data-ck-markdown-copy="blank-lines"]'
  );

  if (last !== null) {
    const after = range.cloneRange();
    after.setStartBefore(last);
    value += `\n${after.toString()}`;
  }

  return value;
};

// Ranges.

const wrapIn = (fragment: DocumentFragment, tag: string) => {
  const wrapper = (fragment.ownerDocument ?? document).createElement(tag);
  wrapper.append(...fragment.childNodes);
  fragment.append(wrapper);
};

/** A range inside the root. */
const serializeRange = (
  root: Element,
  source: Range,
  includeCollapsed = false,
  isElement = false
): SerializedCopy | null => {
  const range = source.cloneRange();

  if (!rangeInside(range, root)) {
    return null;
  }

  if (!includeCollapsed) {
    // Math widening is skipped: there is no math markup to widen to.
  }

  const marked = markedAncestor(range, root);
  const mode = copyMode(marked);

  if (mode === "exclude") {
    return null;
  }

  if (mode === "code-block") {
    const selected = range.toString();

    const whole =
      range.startContainer === range.endContainer &&
      range.startOffset === 0 &&
      range.endOffset === range.startContainer.childNodes.length &&
      (range.startContainer === marked ||
        closestElement(range.startContainer, "svg") === range.startContainer);

    const value =
      (whole || selected.length === 0
        ? marked?.getAttribute(TEXT_ATTRIBUTE)
        : null) ?? selected;

    const pre = preformatted(root.ownerDocument, value);

    const language = marked
      ?.querySelector("code[data-language]")
      ?.getAttribute("data-language");

    if (language !== null && language !== undefined) {
      pre.querySelector("code")?.setAttribute("data-language", language);
    }

    return { htmlText: pre.outerHTML, plainText: value };
  }

  if (mode === "blank-lines") {
    const value = range.toString();

    return { htmlText: "<p></p>".repeat(value.length), plainText: value };
  }

  const cloned = cloneRange(range);
  const link = closestElement(range.commonAncestorContainer, "a[href]");

  if (link !== null && root.contains(link)) {
    const wrapper = link.cloneNode(false);
    wrapper.appendChild(cloned);
    cloned.appendChild(wrapper);
  }

  if (includeCollapsed) {
    for (const hidden of cloned.querySelectorAll(
      '[inert][aria-hidden="true"]'
    )) {
      hidden.removeAttribute("aria-hidden");
    }
  }

  // Image replacement only acts on images inside host image components, so the rich
  // fragment is always the one built from the clone.
  const rich = richFragment(cloned);

  if (mode === "inline-code") {
    wrapIn(rich, "code");
  }

  const html = htmlOf(rich);

  if (isElement) {
    for (const code of rich.querySelectorAll(`code[${TEXT_ATTRIBUTE}]`)) {
      code.textContent = code.getAttribute(TEXT_ATTRIBUTE);
    }
  }

  const plain = plainOf(rich, range);

  return plain.length === 0 ? null : { htmlText: html, plainText: plain };
};

/** A selection that starts in the root and ends outside it. */
const serializeAcross = (source: Range): SerializedCopy | null => {
  const range = source.cloneRange();
  const rich = richFragment(cloneRange(range));
  const plain = plainOf(rich, range);

  return plain.length === 0
    ? null
    : { htmlText: htmlOf(rich), plainText: plain };
};

/** The current selection as html and text, or null. */
export const serializeSelection = (
  root: Element,
  selection: Selection | null = root.ownerDocument.getSelection()
): SerializedCopy | null => {
  if (
    selection === null ||
    selection.rangeCount === 0 ||
    selection.isCollapsed
  ) {
    return null;
  }

  const range = selection.getRangeAt(0);

  if (rangeInside(range, root)) {
    const editable = closestElement(range.startContainer, EDITABLE_SELECTOR);

    return editable !== null &&
      editable === closestElement(range.endContainer, EDITABLE_SELECTOR)
      ? null
      : serializeRange(root, range);
  }

  return root.contains(range.startContainer) ? serializeAcross(range) : null;
};

/** The whole content of an element as html and text. */
export const serializeElement = (root: Element): SerializedCopy | null => {
  const range = root.ownerDocument.createRange();
  range.selectNodeContents(root);

  return serializeRange(root, range, false, true);
};

/** Writes the selection to a copy event as html and text. */
export const writeSelectionToCopyEvent = (
  event: ClipboardEvent,
  root: Element
): void => {
  if (event.defaultPrevented || event.clipboardData === null) {
    return;
  }

  const copy = serializeSelection(root);

  if (copy === null) {
    return;
  }

  event.clipboardData.setData("text/html", copy.htmlText);
  event.clipboardData.setData("text/plain", copy.plainText);
  event.preventDefault();
};

/**
 * Writes a map of formats: one `ClipboardItem`
 * with a blob per type, or only `text/plain` through `writeText` where the
 * async clipboard has no `write`. Resolves false when the clipboard is missing
 * or the write is rejected.
 */
export const writeClipboardFormats = async (
  formats: Record<string, string>
): Promise<boolean> => {
  const clipboard =
    typeof navigator === "undefined" ? undefined : navigator.clipboard;

  if (clipboard === undefined) {
    return false;
  }

  try {
    if ("write" in clipboard && typeof ClipboardItem !== "undefined") {
      await clipboard.write([
        new ClipboardItem(
          Object.fromEntries(
            Object.entries(formats).map(([type, value]) => [
              type,
              new Blob([value], { type }),
            ])
          )
        ),
      ]);
    } else {
      await clipboard.writeText(formats["text/plain"] ?? "");
    }

    return true;
  } catch {
    return false;
  }
};

"use client";

/* oxlint-disable typescript/strict-boolean-expressions -- Branches test optional handlers and flags by truthiness. */

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogBody,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogSection,
  DialogTitle,
} from "@/components/ui/dialog";
import { copyMarkdownText } from "@/components/ui/markdown";
import { TooltipHint } from "@/components/ui/tooltip";
import { resolvesToExternalWeb } from "@/lib/link-destination";
import { createContext, useState } from "react";
import type {
  ComponentProps,
  ComponentType,
  SubmitEvent,
  MouseEvent,
  ReactNode,
} from "react";

/** `restricted` asks before a link opens. */
export type ExternalResourcePolicy = "allow" | "restricted";

/** A restricted ancestor makes every link below it restricted. */
export const ExternalResourcePolicyContext =
  createContext<ExternalResourcePolicy>("allow");

export interface LinkProviderRenderOptions {
  customIcon?: ReactNode;
  customTooltip?: ReactNode;
  tooltipDelayDuration?: number;
}

export interface LinkProviderProps {
  children: (options?: LinkProviderRenderOptions) => ReactNode;
  href: string;
}

export type LinkProviderComponent = ComponentType<LinkProviderProps>;

/**
 * The host's link provider. When one is set, the component hands it the
 * link and a render function, and the provider decides how the link shows
 * (preview card, custom icon, custom tooltip). Default none.
 */
export const LinkProviderContext = createContext<LinkProviderComponent | null>(
  null
);

const HTTP_URL = /^https?:\/\//iu;

export interface ExternalLinkProps extends Omit<ComponentProps<"a">, "href"> {
  href: string;
  /** Runs when the link is opened. */
  onActivate?: () => void;
  /** Opens the link after confirmation. Default: a new tab without opener. */
  onOpen?: (href: string) => void;
  /** An http(s) link asks before it opens. */
  requiresConfirmation?: boolean;
  showCopyLinkInConfirmation?: boolean;
  tooltipContent?: ReactNode;
  tooltipDelayDuration?: number;
}

export type ExternalLinkComponent = ComponentType<ExternalLinkProps>;

const openInNewTab = (href: string) => {
  window.open(href, "_blank", "noopener,noreferrer");
};

/** The dialog that stands between a restricted link and the website. */
const ExternalLinkConfirmation = ({
  href,
  onClose,
  onOpen,
  showCopyLink,
}: {
  href: string;
  onClose: () => void;
  onOpen: () => void;
  showCopyLink: boolean;
}) => {
  const submit = (event: SubmitEvent<HTMLFormElement>) => {
    event.preventDefault();
    onClose();
    onOpen();
  };

  return (
    <Dialog
      onOpenChange={(open) => {
        if (!open) {
          onClose();
        }
      }}
      open
      size="compact"
    >
      <DialogBody as="form" onSubmit={submit}>
        <DialogSection>
          <DialogHeader
            subtitle={
              <DialogDescription className="contents">
                Confirm before connecting to this website
              </DialogDescription>
            }
            title={
              <DialogTitle className="contents">
                Open external link?
              </DialogTitle>
            }
          />
        </DialogSection>
        <DialogSection>
          <div
            className="rounded-md bg-panel-secondary/92 p-3 text-sm break-all text-text-muted"
            data-testid="external-link-confirmation-url"
          >
            {href}
          </div>
        </DialogSection>
        <DialogSection>
          <DialogFooter>
            {showCopyLink ? (
              <Button
                color="secondary"
                onClick={() => {
                  copyMarkdownText(href)
                    .then((copied) => {
                      if (copied) {
                        onClose();
                      }

                      return copied;
                    })
                    .catch(() => false);
                }}
                type="button"
              >
                Copy link
              </Button>
            ) : null}
            <Button color="secondary" onClick={onClose} type="button">
              Cancel
            </Button>
            <Button type="submit">Open link</Button>
          </DialogFooter>
        </DialogSection>
      </DialogBody>
    </Dialog>
  );
};

/**
 * The link the prose renders by default. It is
 * an anchor that opens in a new tab with `rel="noopener noreferrer"`. With
 * `requiresConfirmation`, a click, a middle click or a keyboard activation on
 * an http(s) link opens the confirmation dialog instead, and the context menu
 * and drag are blocked so nothing opens the link around the dialog. Host
 * services (in-app browser tabs, downloads, the link context
 * menu with its app destinations) stay with the host and replace this
 * component through `ExternalLinkComponent`.
 */
export const ExternalLink = ({
  children,
  href,
  onActivate,
  onAuxClick,
  onClick,
  onContextMenu,
  onDragStart,
  onOpen = openInNewTab,
  requiresConfirmation = false,
  showCopyLinkInConfirmation = false,
  tooltipContent,
  tooltipDelayDuration,
  ...props
}: ExternalLinkProps) => {
  const [confirming, setConfirming] = useState(false);
  const external = HTTP_URL.test(href);

  const confirm =
    requiresConfirmation && (external || resolvesToExternalWeb(href));

  const activate = (event: MouseEvent<HTMLAnchorElement>) => {
    if (confirm) {
      event.preventDefault();
      setConfirming(true);

      return;
    }

    onActivate?.();
  };

  const link = (
    <a
      {...props}
      href={href}
      onAuxClick={(event) => {
        onAuxClick?.(event);

        if (!event.defaultPrevented && event.button === 1) {
          activate(event);
        }
      }}
      onClick={(event) => {
        onClick?.(event);

        if (!event.defaultPrevented) {
          activate(event);
        }
      }}
      onContextMenu={(event) => {
        if (confirm) {
          event.preventDefault();

          return;
        }

        onContextMenu?.(event);
      }}
      onDragStart={(event) => {
        onDragStart?.(event);

        if (confirm) {
          event.preventDefault();
        }
      }}
      rel={external ? "noopener noreferrer" : props.rel}
      target={external ? "_blank" : props.target}
    >
      {children}
    </a>
  );

  return (
    <>
      {tooltipContent === undefined ? (
        link
      ) : (
        <TooltipHint
          cloneCustomTrigger
          content={tooltipContent}
          delayDuration={tooltipDelayDuration}
        >
          {link}
        </TooltipHint>
      )}
      {confirming ? (
        <ExternalLinkConfirmation
          href={href}
          onClose={() => {
            setConfirming(false);
          }}
          onOpen={() => {
            onActivate?.();
            onOpen(href);
          }}
          showCopyLink={showCopyLinkInConfirmation}
        />
      ) : null}
    </>
  );
};

"use client";

/* oxlint-disable anti-slop/require-safety-comment-for-type-assertion, typescript/no-unsafe-type-assertion -- SAFETY: custom properties in style objects. */
/* oxlint-disable typescript/consistent-return, unicorn/prefer-code-point -- Functions return a value only on the fading path; the segmenter fallback tests UTF-16 units. */

/* oxlint-disable anti-slop/no-known-value-widening -- Lookup tables and parse results are typed by their string keys. */
/* oxlint-disable anti-slop/no-unsafe-dictionary-type -- Hast element properties are an open attribute dictionary. */
/* oxlint-disable eslint/prefer-destructuring -- Stylistic. */
/* oxlint-disable eslint/require-unicode-regexp -- The segment patterns are kept. */
/* oxlint-disable react/refs -- The timeline lives in a ref so the segment ref callbacks read the current clock. */
/* oxlint-disable typescript/prefer-nullish-coalescing, typescript/strict-boolean-expressions -- Branches test optional values by truthiness. */

import type {
  CSSProperties,
  ReactNode,
  RefCallback,
  SyntheticEvent,
} from "react";
import { createElement } from "react";

import type { HastElement, HastNode, HastText } from "./parse";

/**
 * The streaming text fade of the chat prose: the timeline, the segment props,
 * the text splitter, the span builder, and the key allocator with its
 * collector. The collector walks hast instead of marked
 * tokens, in document order, so a segment keeps its key while text streams in.
 */

// ---- timeline ----------------------------------------------------

export interface FadeSegmentTimeline {
  delayMsByKey: Map<string, number>;
  nextSegmentStartAtMs: number;
  segmentKeyByElement: WeakMap<HTMLElement, string>;
  settledKeys: Set<string>;
  startAtMsByKey: Map<string, number>;
}

export const createFadeSegmentTimeline = (): FadeSegmentTimeline => ({
  delayMsByKey: new Map(),
  nextSegmentStartAtMs: 0,
  segmentKeyByElement: new WeakMap(),
  settledKeys: new Set(),
  startAtMsByKey: new Map(),
});

interface FadeDelay {
  fadeSegmentDelayMs: number;
  fadeSegmentMaxDelayMs?: number;
}

/** The first time an element shows a segment it gets the next free start. */
const placeSegment = ({
  element,
  fadeSegmentDelayMs,
  fadeSegmentMaxDelayMs,
  segmentKey,
  timeline,
}: FadeDelay & {
  element: HTMLElement;
  segmentKey: string;
  timeline: FadeSegmentTimeline;
}) => {
  if (timeline.segmentKeyByElement.get(element) === segmentKey) {
    return;
  }

  const now = performance.now();
  const known = timeline.startAtMsByKey.get(segmentKey);

  const start =
    known ??
    Math.min(
      Math.max(timeline.nextSegmentStartAtMs, now),
      fadeSegmentMaxDelayMs === undefined
        ? Number.POSITIVE_INFINITY
        : now + fadeSegmentMaxDelayMs
    );

  const delay = Math.round(start - now);

  if (known === undefined) {
    timeline.startAtMsByKey.set(segmentKey, start);
    timeline.delayMsByKey.set(segmentKey, delay);
    timeline.nextSegmentStartAtMs = start + fadeSegmentDelayMs;
  }

  timeline.segmentKeyByElement.set(element, segmentKey);
  element.style.setProperty("--fade-delay", `${delay}ms`);
};

const indexDelay = ({
  fadeSegmentDelayMs,
  fadeSegmentMaxDelayMs,
  segmentIndex,
}: FadeDelay & { segmentIndex: number }): number =>
  Math.min(
    segmentIndex * fadeSegmentDelayMs,
    fadeSegmentMaxDelayMs ?? Number.POSITIVE_INFINITY
  );

export interface FadeSegmentProps {
  className?: string;
  onAnimationEnd?: (event: SyntheticEvent<HTMLElement>) => void;
  ref?: RefCallback<HTMLElement>;
  style?: CSSProperties;
}

/** Class, delay and bookkeeping for one fading element. */
export const fadeSegmentProps = ({
  className,
  fadeSegmentDelayMs,
  fadeSegmentMaxDelayMs,
  segmentIndex,
  segmentKey,
  timeline,
}: FadeDelay & {
  className: string;
  segmentIndex: number;
  segmentKey?: string;
  timeline?: FadeSegmentTimeline;
}): FadeSegmentProps => {
  const settled =
    segmentKey !== undefined && timeline?.settledKeys.has(segmentKey);

  const tracked =
    !settled && segmentKey !== undefined && timeline !== undefined;

  const delayMs =
    (segmentKey === undefined
      ? undefined
      : timeline?.delayMsByKey.get(segmentKey)) ??
    indexDelay({ fadeSegmentDelayMs, fadeSegmentMaxDelayMs, segmentIndex });

  return {
    className: settled ? undefined : className,
    onAnimationEnd: tracked
      ? (event) => {
          if (event.target === event.currentTarget) {
            timeline.settledKeys.add(segmentKey);
          }
        }
      : undefined,
    ref: tracked
      ? (element) => {
          if (element !== null) {
            placeSegment({
              element,
              fadeSegmentDelayMs,
              fadeSegmentMaxDelayMs,
              segmentKey,
              timeline,
            });
          }
        }
      : undefined,
    style:
      fadeSegmentDelayMs <= 0
        ? undefined
        : ({ "--fade-delay": `${delayMs}ms` } as CSSProperties),
  };
};

// ---- splitting text --------------------------------------

const BLANK = /^\s*$/;
const WORD_WITH_SPACE = /\s*\S+(?:\s+|$)/g;

const isAsciiLetterOrDigit = (text: string, index: number): boolean => {
  if (index >= text.length) {
    return false;
  }

  const code = text.charCodeAt(index);

  return (
    (code >= 48 && code <= 57) ||
    (code >= 65 && code <= 90) ||
    (code >= 97 && code <= 122)
  );
};

const isAscii = (text: string): boolean => {
  for (let index = 0; index < text.length; index += 1) {
    if (text.charCodeAt(index) > 127) {
      return false;
    }
  }

  return true;
};

/** Runs of ASCII letters and digits are segments, other characters join the previous one. */
const splitAscii = (text: string): string[] => {
  const segments: string[] = [];
  let index = 0;

  while (index < text.length) {
    if (isAsciiLetterOrDigit(text, index)) {
      const start = index;

      while (isAsciiLetterOrDigit(text, index)) {
        index += 1;
      }

      segments.push(text.slice(start, index));
      continue;
    }

    const last = Math.max(segments.length - 1, 0);
    segments[last] ??= "";
    segments[last] += text[index];
    index += 1;
  }

  return segments;
};

export const splitFadeText = (
  text: string,
  segmenter: Intl.Segmenter | null
): string[] => {
  if (isAscii(text)) {
    return splitAscii(text);
  }

  if (segmenter === null) {
    const parts = [...(text.match(WORD_WITH_SPACE) ?? [])];

    return parts.length > 0 || text.length === 0 ? parts : [text];
  }

  const segments: string[] = [];

  for (const { segment, isWordLike } of segmenter.segment(text)) {
    if (BLANK.test(segment) || !isWordLike) {
      const last = Math.max(segments.length - 1, 0);
      segments[last] ??= "";
      segments[last] += segment;
    } else {
      segments.push(segment);
    }
  }

  return segments;
};

/** `new Intl.Segmenter(undefined, { granularity: "word" })`, or null where it is missing. */
export const createWordSegmenter = (): Intl.Segmenter | null => {
  try {
    return new Intl.Segmenter(undefined, { granularity: "word" });
  } catch {
    return null;
  }
};

// Keys.

interface PreviousSegment {
  content: string;
  key: string;
}

export interface FadeKeyState {
  nextSegmentId: number;
  previousSegments: PreviousSegment[];
}

export const createFadeKeyState = (): FadeKeyState => ({
  nextSegmentId: 0,
  previousSegments: [],
});

/**
 * A segment keeps the key of the previous segment at its index
 * when the content matches or extends it, then of an unused previous segment
 * with the same content, else it gets a new key. Mutates `state`.
 */
const allocateKeys = (contents: string[], state: FadeKeyState): string[] => {
  const unused = new Set(state.previousSegments.keys());
  let byContent: Map<string, number[]> | undefined;

  const keys = contents.map((content, index) => {
    const same = state.previousSegments[index];

    if (
      same !== undefined &&
      unused.has(index) &&
      (same.content === content ||
        (same.content.length > 0 && content.startsWith(same.content)))
    ) {
      unused.delete(index);

      return same.key;
    }

    if (byContent === undefined && unused.size > 0) {
      byContent = new Map();

      for (let at = state.previousSegments.length - 1; at >= 0; at -= 1) {
        const previous = state.previousSegments[at];

        if (previous === undefined) {
          continue;
        }

        const list = byContent.get(previous.content) ?? [];
        list.push(at);
        byContent.set(previous.content, list);
      }
    }

    const candidates = byContent?.get(content);
    let found = candidates?.pop();

    while (found !== undefined && !unused.has(found)) {
      found = candidates?.pop();
    }

    const previous =
      found === undefined ? undefined : state.previousSegments[found];

    if (found !== undefined && previous !== undefined) {
      unused.delete(found);

      return previous.key;
    }

    const key = `fade-segment-${state.nextSegmentId}`;
    state.nextSegmentId += 1;

    return key;
  });

  state.previousSegments = keys.map((key, index) => ({
    content: contents[index] ?? "",
    key,
  }));

  return keys;
};

/** A candidate is allocated per render and committed once it is on screen. */
export const createFadeKeyStore = () => {
  let committed = createFadeKeyState();

  return {
    commit: (state: FadeKeyState) => {
      committed = state;
    },
    createCandidate: (): FadeKeyState => ({
      nextSegmentId: committed.nextSegmentId,
      previousSegments: committed.previousSegments,
    }),
  };
};

// Collecting segments.

interface TextEntry {
  keys: string[];
  segments: string[];
  startIndex: number;
}

interface ListItemEntry {
  segmentKey?: string;
  startIndex: number;
}

export interface FadeSegments {
  listItems: WeakMap<HastElement, ListItemEntry>;
  text: WeakMap<HastText, TextEntry>;
}

// Code (code, codespan) has no text tokens, so it never fades.
const CODE_TAGS = new Set(["code", "pre"]);

/**
 * Splits every text node into segments in document order,
 * numbers them across the whole document, and gives each its key. A list item
 * is decorated with the key of the first segment it contains.
 */
export const collectFadeSegments = (
  nodes: HastNode[],
  segmenter: Intl.Segmenter | null,
  state: FadeKeyState
): FadeSegments => {
  const contents: string[] = [];
  const textEntries: TextEntry[] = [];
  const itemEntries: ListItemEntry[] = [];

  const result: FadeSegments = {
    listItems: new WeakMap(),
    text: new WeakMap(),
  };

  const visit = (list: HastNode[]) => {
    for (const node of list) {
      if (node.type === "text") {
        // Newline text between blocks is layout, not a text token.
        if (node.value === "\n") {
          continue;
        }

        const segments = splitFadeText(node.value, segmenter);
        const entry = { keys: [], segments, startIndex: contents.length };
        result.text.set(node, entry);
        textEntries.push(entry);
        contents.push(...segments);
      } else if (node.type === "element" && !CODE_TAGS.has(node.tagName)) {
        if (node.tagName === "li") {
          const item = { startIndex: contents.length } as ListItemEntry;
          result.listItems.set(node, item);
          itemEntries.push(item);
        }

        visit(node.children);
      }
    }
  };

  visit(nodes);
  const keys = allocateKeys(contents, state);

  for (const entry of textEntries) {
    entry.keys = keys.slice(
      entry.startIndex,
      entry.startIndex + entry.segments.length
    );
  }

  for (const item of itemEntries) {
    item.segmentKey = keys[item.startIndex];
  }

  return result;
};

// ---- rendering -----------------------------------------------------

export interface FadeConfig extends FadeDelay {
  /** Class of a fading span. */
  fadeInClassName: string;
  /** Class of a list item whose marker fades. */
  listDecorationClassName: string;
  segments: FadeSegments;
  timeline: FadeSegmentTimeline;
}

/** One span per segment. */
export const renderFadeText = (
  node: HastText,
  config: FadeConfig
): ReactNode => {
  const entry = config.segments.text.get(node);

  if (entry === undefined) {
    return;
  }

  return entry.segments.map((segment, offset) =>
    createElement(
      "span",
      {
        ...fadeSegmentProps({
          className: config.fadeInClassName,
          fadeSegmentDelayMs: config.fadeSegmentDelayMs,
          fadeSegmentMaxDelayMs: config.fadeSegmentMaxDelayMs,
          segmentIndex: entry.startIndex + offset,
          segmentKey: entry.keys[offset],
          timeline: config.timeline,
        }),
        key: entry.keys[offset] ?? `fade-${entry.startIndex + offset}`,
      },
      segment
    )
  );
};

/** The fade props of a list item (a task item fades whole, others fade their marker). */
export const listItemFadeProps = (
  node: HastElement,
  config: FadeConfig
): FadeSegmentProps | undefined => {
  const entry = config.segments.listItems.get(node);

  if (entry === undefined) {
    return;
  }

  const task = Array.isArray(node.properties.className)
    ? node.properties.className.includes("task-list-item")
    : false;

  return fadeSegmentProps({
    className: task ? config.fadeInClassName : config.listDecorationClassName,
    fadeSegmentDelayMs: config.fadeSegmentDelayMs,
    fadeSegmentMaxDelayMs: config.fadeSegmentMaxDelayMs,
    segmentIndex: entry.startIndex,
    segmentKey: entry.segmentKey,
    timeline: config.timeline,
  });
};

/* oxlint-disable anti-slop/no-known-value-widening -- Lookup tables and parse results are typed by their string keys. */
/* oxlint-disable eslint/no-nested-ternary -- Stylistic; kept in the form. */
/* oxlint-disable eslint/prefer-destructuring -- Stylistic. */
/* oxlint-disable eslint/prefer-named-capture-group -- The parser reads capture groups by position. */
/* oxlint-disable eslint/require-unicode-regexp -- The patterns are CommonMark, GFM and ANSI grammar kept without the u flag, which rejects the escaped punctuation classes they use. */
/* oxlint-disable unicorn/prefer-code-point -- Stylistic; the code compares UTF-16 code units of the escape and BOM characters. */

/**
 * Front-matter reader for the markdown file preview: a leading
 * `---` block with flat `key: value` entries, `key:` followed by `- item`
 * lists, and inline `[a, b]` lists. Nested maps and block scalars are skipped.
 */

export type FrontMatterValue = string | string[];

export interface FrontMatterEntry {
  key: string;
  value: FrontMatterValue;
}

export interface FrontMatter {
  body: string;
  entries: FrontMatterEntry[];
}

const BLOCK_SCALAR = /^[>|][+-]?$/;
const FENCE_LINE = /^-{3,}$/;
const LIST_ITEM = /^[ \t]*-[ \t]*(.*)$/;
const INDENTED = /^[ \t]/;
const WHITESPACE = /\s/;

const splitLines = (value: string): string[] =>
  value.replaceAll("\r\n", "\n").replaceAll("\r", "\n").split("\n");

const lineEnd = (value: string, from: number): number => {
  const newline = value.indexOf("\n", from);

  if (newline === -1) {
    return value.length;
  }

  return value[newline - 1] === "\r" ? newline - 1 : newline;
};

const nextLineStart = (value: string, at: number): number => {
  if (value[at] === "\r" && value[at + 1] === "\n") {
    return at + 2;
  }

  return value[at] === "\n" ? at + 1 : at;
};

const skipWhitespace = (value: string, from: number): number => {
  let index = from;

  while (index < value.length && WHITESPACE.test(value[index] ?? "")) {
    index += 1;
  }

  return index;
};

const escapeValue = (char: string): string => {
  switch (char) {
    case "n": {
      return "\n";
    }

    case "r": {
      return "\r";
    }

    case "t": {
      return "\t";
    }

    default: {
      return char;
    }
  }
};

const readQuoted = (
  value: string,
  from: number,
  mustEnd: boolean
): { nextIndex: number; value: string } | null => {
  const quote = value[from];
  let result = "";
  let index = from + 1;

  while (index < value.length) {
    const char = value[index] ?? "";

    if (quote === '"' && char === "\\") {
      if (index + 1 >= value.length) {
        return null;
      }

      result += escapeValue(value[index + 1] ?? "");
      index += 2;
    } else if (quote === "'" && char === "'" && value[index + 1] === "'") {
      result += "'";
      index += 2;
    } else {
      if (char === quote) {
        const after = index + 1;

        if (mustEnd && value.slice(after).trim().length > 0) {
          return null;
        }

        return { nextIndex: after, value: result };
      }

      result += char;
      index += 1;
    }
  }

  return null;
};

const looksNested = (value: string): boolean =>
  value.startsWith("-") || /:\s/.test(value);

const readScalar = (value: string): string | null => {
  const first = value[0];

  if (
    value.startsWith("[") ||
    value.startsWith("{") ||
    BLOCK_SCALAR.test(value)
  ) {
    return null;
  }

  if (first === '"' || first === "'") {
    return readQuoted(value, 0, true)?.value ?? null;
  }

  return value;
};

const readFlowItem = (
  value: string,
  from: number
): { nextIndex: number; value: string } | null => {
  const first = value[from];

  if (first === '"' || first === "'") {
    return readQuoted(value, from, false);
  }

  if (first === "[" || first === "{") {
    return null;
  }

  let end = from;

  while (end < value.length && value[end] !== "," && value[end] !== "]") {
    end += 1;
  }

  const item = value.slice(from, end).trim();

  return item.length === 0 || looksNested(item)
    ? null
    : { nextIndex: end, value: item };
};

const readFlowList = (value: string): string[] | null => {
  const items: string[] = [];
  let index = 1;

  while (index < value.length) {
    index = skipWhitespace(value, index);

    if (value[index] === "]") {
      return value.slice(index + 1).trim().length === 0 ? items : null;
    }

    const item = readFlowItem(value, index);

    if (item === null) {
      return null;
    }

    items.push(item.value);
    index = skipWhitespace(value, item.nextIndex);

    if (value[index] === ",") {
      index += 1;
    } else {
      return value[index] === "]" && value.slice(index + 1).trim().length === 0
        ? items
        : null;
    }
  }

  return null;
};

const readInlineValue = (value: string): FrontMatterValue | null => {
  if (BLOCK_SCALAR.test(value) || value.startsWith("{")) {
    return null;
  }

  return value.startsWith("[") ? readFlowList(value) : readScalar(value);
};

const readBlockList = (
  lines: string[],
  from: number
): { items: string[]; nextIndex: number } | null => {
  const items: string[] = [];
  let index = from;
  let found = false;

  while (index < lines.length) {
    const match = LIST_ITEM.exec(lines[index] ?? "");

    if (match === null) {
      break;
    }

    found = true;
    const raw = (match[1] ?? "").trim();
    const first = raw[0];

    const item =
      first === '"' || first === "'"
        ? readScalar(raw)
        : looksNested(raw)
          ? null
          : readScalar(raw);

    if (item !== null) {
      items.push(item);
    }

    index += 1;
  }

  return found ? { items, nextIndex: index } : null;
};

const readEntries = (
  block: string
): { entries: FrontMatterEntry[]; hasMetadataSyntax: boolean } => {
  const lines = splitLines(block);
  const entries: FrontMatterEntry[] = [];
  let hasMetadataSyntax = false;
  let index = 0;

  while (index < lines.length) {
    const line = lines[index] ?? "";
    const trimmed = line.trim();

    if (
      trimmed.length === 0 ||
      trimmed.startsWith("#") ||
      INDENTED.test(line)
    ) {
      index += 1;
      continue;
    }

    const colon = line.indexOf(":");
    const key = colon === -1 ? "" : line.slice(0, colon).trim();

    if (colon <= 0 || key.length === 0 || key.startsWith("-")) {
      index += 1;
      continue;
    }

    hasMetadataSyntax = true;
    const rest = line.slice(colon + 1).trim();

    if (rest.length === 0) {
      const list = readBlockList(lines, index + 1);

      if (list !== null) {
        if (list.items.length > 0) {
          entries.push({ key, value: list.items });
        }

        index = list.nextIndex;
        continue;
      }

      const following = lines[index + 1];

      if (
        following !== undefined &&
        INDENTED.test(following) &&
        following.trim().length > 0
      ) {
        index += 1;
        continue;
      }

      entries.push({ key, value: "" });
      index += 1;
      continue;
    }

    const value = readInlineValue(rest);

    if (value !== null && (!Array.isArray(value) || value.length > 0)) {
      entries.push({ key, value });
    }

    index += 1;
  }

  return { entries, hasMetadataSyntax };
};

/** Returns the metadata entries and the body, or `null` without front matter. */
export const parseFrontMatter = (source: string): FrontMatter | null => {
  const offset = source.charCodeAt(0) === 65_279 ? 1 : 0;
  const firstEnd = lineEnd(source, offset);

  if (!FENCE_LINE.test(source.slice(offset, firstEnd).trim())) {
    return null;
  }

  const blockStart = nextLineStart(source, firstEnd);
  let cursor = blockStart;

  while (cursor < source.length) {
    const end = lineEnd(source, cursor);

    if (FENCE_LINE.test(source.slice(cursor, end).trim())) {
      const parsed = readEntries(source.slice(blockStart, cursor));

      return parsed.hasMetadataSyntax
        ? {
            body: source.slice(nextLineStart(source, end)),
            entries: parsed.entries,
          }
        : null;
    }

    cursor = nextLineStart(source, end);

    if (cursor === end) {
      break;
    }
  }

  return null;
};

/* oxlint-disable anti-slop/no-runtime-typeof, typescript/promise-function-async -- A node is a string or a token, and ReactNode includes promises though these functions return content synchronously. */
/* oxlint-disable shadcn/no-inline-styles -- The component styles each line number inline. */
/* oxlint-disable shadcn/no-unknown-classes -- Prism token class names and the react-syntax-highlighter line number class are kept as styling hooks. */

import type { ReactNode } from "react";

import { tokenizeCode } from "./highlight";
import type { MarkdownNode, MarkdownToken } from "./highlight";

type TokenClassName = (classes: readonly string[]) => string;

const renderNode = (
  node: MarkdownNode,
  key: number,
  tokenClassName: TokenClassName
): ReactNode => {
  if (typeof node === "string") {
    return node;
  }

  return (
    <span className={tokenClassName(node.classes)} key={key}>
      {node.content.map((child, index) =>
        renderNode(child, index, tokenClassName)
      )}
    </span>
  );
};

type Line = MarkdownNode[];

const wrap = (
  text: string,
  wrappers: readonly (readonly string[])[]
): MarkdownNode => {
  let node: MarkdownNode = text;

  for (const classes of wrappers.toReversed()) {
    const wrapped: MarkdownToken = { classes, content: [node] };
    node = wrapped;
  }

  return node;
};

/** Splits tokens at newlines, keeping each wrapping token on every line it spans. */
const splitIntoLines = (nodes: readonly MarkdownNode[]): Line[] => {
  const lines: Line[] = [[]];

  const walk = (
    node: MarkdownNode,
    wrappers: readonly (readonly string[])[]
  ) => {
    if (typeof node !== "string") {
      for (const child of node.content) {
        walk(child, [...wrappers, node.classes]);
      }

      return;
    }

    for (const [index, part] of node.split("\n").entries()) {
      if (index > 0) {
        lines.push([]);
      }

      if (part !== "") {
        lines.at(-1)?.push(wrap(part, wrappers));
      }
    }
  };

  for (const node of nodes) {
    walk(node, []);
  }

  return lines;
};

/**
 * The code as react-syntax-highlighter renders it with `useInlineStyles` off:
 * token spans with Prism class names. With line numbers (`showLineNumbers` and
 * `showInlineLineNumbers`) every line is a span that starts with a number span
 * (`comment linenumber react-syntax-highlighter-line-number`, inline-block,
 * min-width `<digits>.25em`, 1em right padding, right aligned, unselectable).
 */
export const highlightLines = (
  code: string,
  language: string,
  showLineNumbers: boolean,
  tokenClassName: TokenClassName
): ReactNode => {
  const nodes = tokenizeCode(code, language);

  if (!showLineNumbers) {
    return nodes.map((node, index) => renderNode(node, index, tokenClassName));
  }

  const lines = splitIntoLines(nodes);
  const minWidth = `${String(lines.length).length}.25em`;

  return lines.map((line, index) => (
    // oxlint-disable-next-line react/no-array-index-key -- lines have no identity besides their position.
    <span key={index}>
      <span
        className="comment linenumber react-syntax-highlighter-line-number"
        style={{
          display: "inline-block",
          minWidth,
          paddingRight: "1em",
          textAlign: "right",
          userSelect: "none",
        }}
      >
        {index + 1}
      </span>
      {line.map((node, nodeIndex) =>
        renderNode(node, nodeIndex, tokenClassName)
      )}
      {index < lines.length - 1 ? "\n" : null}
    </span>
  ));
};

/* oxlint-disable anti-slop/require-safety-comment-for-type-assertion, typescript/no-unsafe-type-assertion -- SAFETY: refractor returns a root whose children are elements and text. */

import type { Element, ElementContent } from "hast";
import bash from "refractor/bash";
import c from "refractor/c";
import clike from "refractor/clike";
import { refractor } from "refractor/core";
import css from "refractor/css";
import diff from "refractor/diff";
import docker from "refractor/docker";
import go from "refractor/go";
import java from "refractor/java";
import javascript from "refractor/javascript";
import json from "refractor/json";
import jsx from "refractor/jsx";
import kotlin from "refractor/kotlin";
import markdown from "refractor/markdown";
import markup from "refractor/markup";
import php from "refractor/php";
import python from "refractor/python";
import ruby from "refractor/ruby";
import scss from "refractor/scss";
import sql from "refractor/sql";
import toml from "refractor/toml";
import tsx from "refractor/tsx";
import typescript from "refractor/typescript";
import yaml from "refractor/yaml";

/**
 * The code block tokenizer. The component registers 24 Prism grammars on
 * react-syntax-highlighter's light build. That build ignores the name it is given and
 * registers the grammar under its own id and aliases, so `jsonc` registers the
 * json grammar again. A name that no grammar owns throws in `highlight`, and
 * the component then renders the code as plain text.
 */

export interface MarkdownToken {
  /** The class list of the token span (`token`, the type, then aliases). */
  classes: readonly string[];
  content: readonly (MarkdownToken | string)[];
}

export type MarkdownNode = MarkdownToken | string;

const GRAMMARS = [
  javascript,
  jsx,
  typescript,
  tsx,
  markup,
  css,
  scss,
  c,
  clike,
  bash,
  json,
  python,
  sql,
  diff,
  markdown,
  yaml,
  toml,
  docker,
  java,
  go,
  php,
  ruby,
  kotlin,
];

for (const grammar of GRAMMARS) {
  refractor.register(grammar);
}

const toNode = (node: ElementContent): MarkdownNode | undefined => {
  if (node.type === "text") {
    return node.value;
  }

  if (node.type !== "element") {
    return undefined;
  }

  const { className } = node.properties;

  return {
    classes: Array.isArray(className) ? className.map(String) : [],
    content: node.children
      .map(toNode)
      .filter((child): child is MarkdownNode => child !== undefined),
  };
};

/**
 * Tokenizes `code`. A language no registered grammar owns (the default
 * is `text`) renders as plain text, as react-syntax-highlighter does.
 */
export const tokenizeCode = (code: string, name: string): MarkdownNode[] => {
  if (name === "" || name === "text" || !refractor.registered(name)) {
    return [code];
  }

  const tree = refractor.highlight(code, name);

  return tree.children
    .map((child) => toNode(child as Element))
    .filter((child): child is MarkdownNode => child !== undefined);
};

import { Check as LucideCheck, Copy as LucideCopy } from "lucide-react";
