  return (
    <Link
      {...props}
      className={cn(
        decorated ? DECORATED_LINK : TEXT_LINK_CLASSES,
        PROSE_LINK_TONE
      )}
      data-underline={decorated ? undefined : "always"}
      requiresConfirmation={policy === "restricted"}
      tooltipContent={
        options?.customTooltip ?? (decorated ? undefined : props.href)
      }
      tooltipDelayDuration={options?.tooltipDelayDuration}
    >
      {label}
    </Link>
  );
};

/**
 * Every link goes through the link provider when one
 * is set (it receives the href and a render function), and the link component
 * renders it. A restricted policy, from the prop or an ancestor, makes the
 * link ask before it opens. A decorated link is the dotted underline without a
 * tooltip; the other appearances show the URL in a tooltip. File and mention
 * resolution, app icons and website previews are host services that arrive as
 * a link provider.
 */
const ProseLink = ({
  children,
  node: _node,
  ...props
}: ComponentProps<"a"> & { node?: unknown }) => {
  const { externalResourcePolicy } = useContext(ProseContext);
  const inherited = useContext(ExternalResourcePolicyContext);
  const Provider = useContext(LinkProviderContext);
  const { href } = props;

  if (!href) {
    return children;
  }

  const policy =
    externalResourcePolicy === "restricted" || inherited === "restricted"
      ? "restricted"
      : "allow";

  const render = (options?: LinkProviderRenderOptions) => (
    <ProseLinkBody {...props} href={href} options={options} policy={policy}>
      {children}
    </ProseLinkBody>
  );

  return Provider ? <Provider href={href}>{render}</Provider> : render();
};

const IMAGE_ENTER =
  "in-data-[markdown-animated]:origin-center in-data-[markdown-animated]:animate-in in-data-[markdown-animated]:fade-in-0 in-data-[markdown-animated]:zoom-in-[.98] in-data-[markdown-animated]:fill-mode-both in-data-[markdown-animated]:[--tw-animation-duration:.18s] in-data-[markdown-animated]:[--tw-ease:ease-out] motion-reduce:in-data-[markdown-animated]:[--tw-animation-duration:0s]";

const ProseImage = ({
  alt,
  className,
  node: _node,
  ...props
}: ComponentProps<"img"> & { node?: unknown }) => (
  // The component renders the image through its media component; this is the
  // plain element with the enter animation.
  // oxlint-disable-next-line next/no-img-element
  <img {...props} alt={alt ?? ""} className={cn(IMAGE_ENTER, className)} />
);

const PROSE_COMPONENTS: MarkdownComponents = {
  ...HEADINGS,
  a: ProseLink,
  blockquote: Blockquote,
  code: MarkdownProseInlineCode,
  hr: HorizontalRule,
  img: ProseImage,
  li: ListItem,
  ol: ProseOrderedList,
  p: Paragraph,
  pre: ProsePre,
  strong: ProseStrong,
  table: ProseTableContainer,
  tbody: ProseTableBody,
  td: TableCell,
  th: TableHeaderCell,
  thead: ProseTableHead,
  tr: TableRow,
  ul: ProseUnorderedList,
};

/**
 * Markdown in the app's chat typography. Block code
 * renders the placeholder block; `hideCodeBlocks` omits it.
 */
export const MarkdownProse = memo(
  ({
    adaptiveStreaming = false,
    allowBasicHtml = false,
    allowWideBlocks = false,
    isStreaming = false,
    animated = isStreaming,
    breakNewLines = false,
    children,
    className,
    components,
    direction = "auto",
    ExternalLinkComponent: LinkComponent,
    externalLinkAppearance = "inline-mention",
    externalResourcePolicy,
    fadeSegmentDelayMs = 0,
    fadeSegmentMaxDelayMs,
    forceCodeBlockWordWrap = false,
    hideCodeBlocks = false,
    onAddSelectedTextToChat,
    renderCodeBlocksAsWritingBlocks,
    renderCodeBlocksImmediately = false,
    renderMath,
    stickyCodeBlockHeader = false,
    tableActions,
    skipHtml,
    textStyle,
    urlTransform = markdownUrlTransform,
  }: MarkdownProseProps) => {
    const mapped = useMemo<MarkdownComponents>(
      () => ({ ...PROSE_COMPONENTS, ...components }),
      [components]
    );

    const context = useMemo(
      () => ({
        ExternalLinkComponent: LinkComponent,
        allowWideBlocks,
        direction,
        externalLinkAppearance,
        externalResourcePolicy,
        forceCodeBlockWordWrap,
        hideCodeBlocks,
        isStreaming,
        onAddSelectedTextToChat,
        renderCodeBlocksAsWritingBlocks,
        renderCodeBlocksImmediately,
        stickyCodeBlockHeader,
        tableActions,
      }),
      [
        allowWideBlocks,
        direction,
        LinkComponent,
        externalLinkAppearance,
        externalResourcePolicy,
        forceCodeBlockWordWrap,
        hideCodeBlocks,
        isStreaming,
        onAddSelectedTextToChat,
        renderCodeBlocksAsWritingBlocks,
        renderCodeBlocksImmediately,
        stickyCodeBlockHeader,
        tableActions,
      ]
    );

    // Fading text numbers its segments across the whole document, so a
    // fading prose renders whole (the component re-lexes every token as well).
    const [timeline] = useState(createFadeSegmentTimeline);
    const [keyStore] = useState(createFadeKeyStore);
    const [segmenter] = useState(createWordSegmenter);
    const candidate = useRef<FadeKeyState | undefined>(undefined);

    const math = renderMath !== false;
    const katex = useKatex(math);

    const rehypePlugins = useMemo(
      () => (katex ? [createRehypeKatex(katex)] : undefined),
      [katex]
    );

    const assistantMessage = textStyle?.kind === "assistant-message";

    const config = useMemo(
      () => ({
        enabled: !animated && !math,
        parse: {
          breakNewLines,
          math: katex !== null,
          tableColumnSizes: true,
          tableMarkdownSource: true,
          taskCheckbox: "leading" as const,
        },
        render: (nodes: Parameters<typeof renderHast>[0]) =>
          renderHast(nodes, {
            allowBasicHtml,
            components: mapped,
            decorate: animated
              ? (prepared) => {
                  const state = keyStore.createCandidate();

                  const fade: FadeConfig = {
                    fadeInClassName: cn(FADE_IN, styles.fadeIn),
                    fadeSegmentDelayMs,
                    fadeSegmentMaxDelayMs,
                    listDecorationClassName: styles.fadeListDecoration ?? "",
                    segments: collectFadeSegments(prepared, segmenter, state),
                    timeline,
                  };

                  candidate.current = state;

                  return {
                    elementProps: (node) => listItemFadeProps(node, fade),
                    renderText: (node) => renderFadeText(node, fade),
                  };
                }
              : assistantMessage
                ? () => ({
                    renderText: (node) => <AssistantText text={node.value} />,
                  })
                : undefined,
            rehypePlugins,
            skipHtml,
            urlTransform,
          }),
      }),
      [
        animated,
        allowBasicHtml,
        breakNewLines,
        katex,
        math,
        rehypePlugins,
        fadeSegmentDelayMs,
        fadeSegmentMaxDelayMs,
        keyStore,
        mapped,
        segmenter,
        skipHtml,
        timeline,
        assistantMessage,
        urlTransform,
      ]
    );

    const content = useIncrementalBlocks(
      children.replaceAll(NEWLINES, "\n"),
      config
    );

    // The keys of this render become the previous ones once it is on screen.
    useLayoutEffect(() => {
      if (candidate.current) {
        keyStore.commit(candidate.current);
      }
    }, [content, keyStore]);

    // A copy event anywhere in the document, in the capture phase,
    // writes the selection inside the prose as markdown text and html.
    const rootRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
      const root = rootRef.current;

      if (root === null) {
        return;
      }

      const listener = (event: ClipboardEvent) => {
        writeSelectionToCopyEvent(event, root);
      };

      root.ownerDocument.addEventListener("copy", listener, { capture: true });

      return () => {
        root.ownerDocument.removeEventListener("copy", listener, {
          capture: true,
        });
      };
    }, []);

    return (
      <ProseContext.Provider value={context}>
        <div
          ref={rootRef}
          className={cn(
            ROOT_CLASSES,
            adaptiveStreaming && styles.adaptiveStreaming,
            className
          )}
          data-ck-markdown-animated={animated ? "" : undefined}
          data-ck-markdown-text-style={textStyle?.kind}
          data-ck-markdown-text-tone={textStyle?.tone}
          dir={direction}
          style={
            {
              "--ck-prose-link-color": textStyle?.linkColor ?? "currentColor",
            } as CSSProperties
          }
        >
          {content.map((child, index) =>
            isValidElement(child) ? (
              child
            ) : (
              <Fragment key={`text-${index}`}>{child}</Fragment>
            )
          )}
        </div>
      </ProseContext.Provider>
    );
  }
);

"use client";

/* oxlint-disable anti-slop/no-object-parameters, anti-slop/no-unknown-parameters, anti-slop/no-unknown-returns, typescript/no-explicit-any, typescript/no-invalid-void-type -- The rehype plugin contract is the unified one: settings of any type and a transformer that may return nothing. */
/* oxlint-disable anti-slop/require-safety-comment-for-type-assertion, typescript/no-unsafe-type-assertion, typescript/no-unsafe-argument, eslint/no-use-before-define -- SAFETY: custom properties in style objects and plugin results checked for type root before use. */

/* oxlint-disable anti-slop/no-known-value-widening -- Lookup tables and parse results are typed by their string keys. */
/* oxlint-disable anti-slop/no-runtime-typeof -- A value may be a string or a list, or a value or a function, as in the components. */
/* oxlint-disable anti-slop/no-unsafe-dictionary-type -- Hast element properties are an open attribute dictionary. */
/* oxlint-disable eslint/complexity -- The parsers are single-pass state machines that follow the reference algorithms branch for branch. */
/* oxlint-disable eslint/prefer-destructuring -- Stylistic. */
/* oxlint-disable eslint/prefer-named-capture-group -- The grammars are written with positional groups, as the reference parsers do. */
/* oxlint-disable eslint/require-unicode-regexp -- The patterns are CommonMark, GFM and ANSI grammar kept without the u flag, which rejects the escaped punctuation classes they use. */
/* oxlint-disable oxc/no-accumulating-spread -- Each element gets its own properties copy. */
/* oxlint-disable react/exhaustive-effect-dependencies, react/memo-dependencies -- The previous result lives in a ref so the next pass can reuse the unchanged blocks. */
/* oxlint-disable react/no-clone-element -- Block outputs are re-keyed with cloneElement so unchanged blocks keep their identity). */
/* oxlint-disable react/no-react-children -- The renderer reads and maps text children. */
/* oxlint-disable react/refs -- The component keeps the latest props in refs during render so timers read current values. */
/* oxlint-disable typescript/no-base-to-string -- URL attributes are strings in practice. */
/* oxlint-disable typescript/prefer-nullish-coalescing, typescript/strict-boolean-expressions -- Branches test optional flags, regex groups and empty strings by truthiness, as react-markdown and the component do. */
/* oxlint-disable unicorn/no-array-for-each -- Stylistic; the loops need the index and the closure. */

import {
  Children,
  cloneElement,
  createElement,
  isValidElement,
  useLayoutEffect,
  useMemo,
  useRef,
} from "react";
import type { ElementType, ReactElement, ReactNode } from "react";

import { AssistantText } from "./assistant-text";
import { parseMarkdownBlocks } from "./parse";
import type { HastElement, HastNode, HastText, ParseOptions } from "./parse";

/**
 * Renderer shared by both prose flavours. It turns the parser's hast nodes
 * into React elements the way react-markdown does, with block-by-block
 * incremental rendering.
 */

export type MarkdownComponents = Partial<Record<string, ElementType>>;

export type MarkdownUrlTransform = (
  url: string,
  key: string,
  node: HastElement
) => string | null | undefined;

export interface HastRoot {
  children: HastNode[];
  type: "root";
}

/** The `this` of a rehype plugin: the part of the unified processor a plugin reads. */
export interface RehypeProcessor {
  data: {
    (): Record<string, unknown>;
    (key: string): unknown;
    (key: string, value: unknown): RehypeProcessor;
  };
}

export type RehypeTransformer = (
  tree: HastRoot,
  file: { data: Record<string, unknown>; messages: unknown[] }
) => HastRoot | undefined | void;

// A plugin is called with its settings and returns a transformer of the tree.
export type RehypePlugin = (
  this: RehypeProcessor,
  ...settings: any[]
) => RehypeTransformer | undefined | void;

/** A plugin, or `[plugin, ...settings]`; a first setting of `false` skips it. */
export type RehypePluggable = RehypePlugin | [RehypePlugin, ...unknown[]];

const createProcessor = (): RehypeProcessor => {
  const store: Record<string, unknown> = {};

  function data(): Record<string, unknown>;
  function data(key: string): unknown;
  function data(key: string, value: unknown): RehypeProcessor;
  function data(key?: string, value?: unknown): unknown {
    if (key === undefined) {
      return store;
    }

    if (arguments.length === 1) {
      return store[key];
    }

    store[key] = value;

    return processor;
  }

  const processor: RehypeProcessor = { data };

  return processor;
};

/**
 * Runs rehype plugins over the hast tree, in order, as unified's `runSync` does
 * after remark-rehype. The tree is copied first because the parser shares
 * its newline nodes between blocks.
 */
export const runRehypePlugins = (
  nodes: HastNode[],
  plugins: readonly RehypePluggable[]
): HastNode[] => {
  let tree: HastRoot = { children: structuredClone(nodes), type: "root" };
  const processor = createProcessor();
  const file = { data: {}, messages: [] };

  for (const pluggable of plugins) {
    const [plugin, ...settings] = Array.isArray(pluggable)
      ? pluggable
      : [pluggable];

    if (settings[0] === false) {
      continue;
    }

    if (settings[0] === true) {
      settings[0] = undefined;
    }

    const transformer = plugin.call(processor, ...settings);

    if (typeof transformer !== "function") {
      continue;
    }

    const result: unknown = transformer(tree, file);

    if (result instanceof Promise) {
      throw new TypeError("`runSync` finished async. Use `run` instead");
    }

    if ((result as HastRoot | undefined)?.type === "root") {
      tree = result as HastRoot;
    }
  }

  return tree.children;
};

/** Hooks that decorate the prepared tree: replace a text node or add props to an element. */
export interface RenderDecorations {
  /** Props merged onto an element; `className` joins and `style` merges. */
  elementProps?: (node: HastElement) => object | undefined;
  /** Replaces the rendering of a text node; `undefined` keeps the plain string. */
  renderText?: (node: HastText) => ReactNode;
}

export interface RenderOptions {
  allowBasicHtml?: boolean;
  allowElement?: (
    element: HastElement,
    index: number,
    parent: HastElement | HastRoot
  ) => boolean | null | undefined;
  allowedElements?: readonly string[];
  components: MarkdownComponents;
  /** Called with the prepared tree (filters and URL transform applied), before rendering. */
  decorate?: (prepared: HastNode[]) => RenderDecorations;
  disallowedElements?: readonly string[];
  /** Rehype plugins, run on the tree before the element filters. */
  rehypePlugins?: readonly RehypePluggable[];
  skipHtml?: boolean;
  unwrapDisallowed?: boolean;
  urlTransform: MarkdownUrlTransform;
}

// react-markdown's `urlAttributes`.
const URL_ATTRIBUTES: Record<string, readonly string[] | null> = {
  action: ["form"],
  cite: ["blockquote", "del", "ins", "q"],
  data: ["object"],
  formAction: ["button", "input"],
  href: ["a", "area", "base", "link"],
  icon: ["menuitem"],
  itemId: null,
  manifest: ["html"],
  ping: ["a", "area"],
  poster: ["video"],
  src: [
    "audio",
    "embed",
    "iframe",
    "img",
    "input",
    "script",
    "source",
    "track",
    "video",
  ],
};

const SAFE_PROTOCOL = /^(https?|ircs?|mailto|xmpp)$/i;

/** react-markdown's default URL transform. */
export const defaultUrlTransform = (value: string): string => {
  const colon = value.indexOf(":");
  const questionMark = value.indexOf("?");
  const numberSign = value.indexOf("#");
  const slash = value.indexOf("/");

  if (
    colon === -1 ||
    (slash !== -1 && colon > slash) ||
    (questionMark !== -1 && colon > questionMark) ||
    (numberSign !== -1 && colon > numberSign) ||
    SAFE_PROTOCOL.test(value.slice(0, colon))
  ) {
    return value;
  }

  return "";
};

/** The default transform that also allows tel:, sms: and data:image/. */
export const markdownUrlTransform: MarkdownUrlTransform = (url) =>
  url.startsWith("tel:") ||
  url.startsWith("sms:") ||
  url.startsWith("data:image/")
    ? url
    : defaultUrlTransform(url);

/** The text a React subtree renders, used for sizing and numeric detection. */
export const textContent = (node: ReactNode): string => {
  let result = "";
  Children.forEach(node, (child) => {
    if (typeof child === "string" || typeof child === "number") {
      result += String(child);
    } else if (
      isValidElement<{ text: string }>(child) &&
      child.type === AssistantText
    ) {
      // Assistant replies render each text node through AssistantText's text prop.
      result += child.props.text;
    } else if (isValidElement<{ children?: ReactNode }>(child)) {
      result += textContent(child.props.children);
    }
  });

  return result;
};

const BASIC_HTML_TAG = /^<(\/?)(b|del|em|i|kbd|s|strong|sub|sup|u)>$/i;
const HTML_BREAK = /^<br\s*\/?>$/i;

const basicHtml = (nodes: HastNode[]): HastNode[] => {
  const result: HastNode[] = [];

  for (let index = 0; index < nodes.length; index += 1) {
    const node = nodes[index];

    if (!node) {
      continue;
    }

    if (node.type !== "raw") {
      result.push(node);
      continue;
    }

    const value = node.value.trim();

    if (HTML_BREAK.test(value)) {
      result.push({
        children: [],
        properties: {},
        tagName: "br",
        type: "element",
      });
      continue;
    }

    const match = BASIC_HTML_TAG.exec(value);

    if (!match || match[1]) {
      continue;
    }

    const tag = match[2]?.toLowerCase();
    let depth = 0;
    let end = index + 1;

    for (; end < nodes.length; end += 1) {
      const next = nodes[end];

      if (next?.type !== "raw") {
        continue;
      }

      const candidate = BASIC_HTML_TAG.exec(next.value.trim());

      if (candidate?.[2]?.toLowerCase() !== tag) {
        continue;
      }

      if (!candidate[1]) {
        depth += 1;
      } else if (depth === 0) {
        break;
      } else {
        depth -= 1;
      }
    }

    if (end < nodes.length && tag) {
      result.push({
        children: basicHtml(nodes.slice(index + 1, end)),
        properties: {},
        tagName: tag,
        type: "element",
      });
      index = end;
    }
  }

  return result;
};

const prepare = (
  nodes: HastNode[],
  parent: HastElement | HastRoot,
  options: RenderOptions
): HastNode[] => {
  const result: HastNode[] = [];
  (options.allowBasicHtml ? basicHtml(nodes) : nodes).forEach((node, index) => {
    if (node.type === "raw") {
      if (!options.skipHtml) {
        result.push({ type: "text", value: node.value });
      }

      return;
    }

    if (node.type === "text") {
      result.push(node);

      return;
    }

    if (node.tagName === "#unwrap") {
      result.push(...prepare(node.children, parent, options));

      return;
    }

    let { properties } = node;

    for (const [attribute, tags] of Object.entries(URL_ATTRIBUTES)) {
      if (
        Object.hasOwn(properties, attribute) &&
        (tags === null || tags.includes(node.tagName))
      ) {
        properties = {
          ...properties,
          [attribute]: options.urlTransform(
            String(properties[attribute] || ""),
            attribute,
            node
          ),
        };
      }
    }

    const current: HastElement = { ...node, properties };

    const disallowed = options.allowedElements
      ? !options.allowedElements.includes(current.tagName)
      : options.disallowedElements?.includes(current.tagName);

    const rejected =
      !disallowed && options.allowElement
        ? !options.allowElement(current, index, parent)
        : false;

    if (disallowed || rejected) {
      if (options.unwrapDisallowed) {
        result.push(...prepare(current.children, parent, options));
      }

      return;
    }

    result.push({
      ...current,
      children: prepare(current.children, current, options),
    });
  });

  return result;
};

const VOID_TAGS = new Set(["br", "hr", "img", "input"]);

const HAST_DATA_OR_ARIA = /^(aria|data)([A-Z][A-Za-z0-9]*)$/;
const UPPER_CASE = /[A-Z]/g;

// Hast names `aria*` and `data*` properties in camel case (`dataFootnoteRef`);
// the DOM attribute is hyphenated. The parser already emits hyphenated names.
const attributeName = (name: string): string => {
  const match = HAST_DATA_OR_ARIA.exec(name);

  return match
    ? `${match[1]}-${(match[2] ?? "").replaceAll(UPPER_CASE, (letter, offset) => `${offset === 0 ? "" : "-"}${letter.toLowerCase()}`)}`
    : name;
};

const toProps = (properties: Record<string, unknown>) => {
  const props: Record<string, unknown> = {};

  for (const [name, value] of Object.entries(properties)) {
    if (value === null || value === undefined || value === false) {
      continue;
    }

    props[attributeName(name)] = Array.isArray(value) ? value.join(" ") : value;
  }

  return props;
};

const mergeProps = (props: Record<string, unknown>, extra: object) => {
  for (const [name, value] of Object.entries(extra)) {
    if (value === undefined) {
      continue;
    }

    if (name === "className") {
      props.className = [props.className, value].filter(Boolean).join(" ");
    } else if (name === "style") {
      props.style = { ...(props.style as object), ...(value as object) };
    } else {
      props[name] = value;
    }
  }
};

// Elements that cannot hold text: whitespace between their children is dropped
// (hast-util-to-jsx-runtime `tableElements`), else React reports a hydration error.
const TABLE_ELEMENTS = new Set(["table", "tbody", "tfoot", "thead", "tr"]);
const WHITESPACE_ONLY = /^\s*$/;

const renderNodes = (
  nodes: HastNode[],
  options: RenderOptions,
  counter: { value: number },
  decorations?: RenderDecorations,
  parentTag?: string
): ReactNode[] => {
  const out: ReactNode[] = [];

  for (const node of nodes) {
    if (
      node.type === "text" &&
      parentTag !== undefined &&
      TABLE_ELEMENTS.has(parentTag) &&
      WHITESPACE_ONLY.test(node.value)
    ) {
      continue;
    }

    if (node.type === "text") {
      const decorated = decorations?.renderText?.(node);

      if (Array.isArray(decorated)) {
        out.push(...decorated);
      } else if (isValidElement(decorated) && decorated.key === null) {
        // A decorated text node sits in a children array beside its siblings, so it needs a key.
        out.push(cloneElement(decorated, { key: `text-${counter.value}` }));
        counter.value += 1;
      } else {
        out.push(decorated ?? node.value);
      }

      continue;
    }

    if (node.type === "raw") {
      out.push(node.value);
      continue;
    }

    const key = `${node.tagName}-${counter.value}`;
    counter.value += 1;
    const Component = options.components[node.tagName] ?? node.tagName;
    const props: Record<string, unknown> = { ...toProps(node.properties), key };
    const extra = decorations?.elementProps?.(node);

    if (extra) {
      mergeProps(props, extra);
    }

    if (typeof Component !== "string") {
      props.node = node;
    }

    const children = VOID_TAGS.has(node.tagName)
      ? []
      : renderNodes(node.children, options, counter, decorations, node.tagName);

    if (children.length === 1) {
      props.children = children[0];
    } else if (children.length > 1) {
      props.children = children;
    }

    out.push(createElement(Component, props));
  }

  return out;
};

/** Renders hast nodes: URL transform, element filters, then component mapping. */
export const renderHast = (
  nodes: HastNode[],
  options: RenderOptions
): ReactNode[] => {
  if (options.allowedElements && options.disallowedElements) {
    throw new Error(
      "Unexpected combined `allowedElements` and `disallowedElements`, expected one or the other"
    );
  }

  const tree =
    options.rehypePlugins && options.rehypePlugins.length > 0
      ? runRehypePlugins(nodes, options.rehypePlugins)
      : nodes;

  const root: HastRoot = { children: tree, type: "root" };

  const prepared = prepare(tree, root, options);

  return renderNodes(
    prepared,
    options,
    { value: 0 },
    options.decorate?.(prepared)
  );
};

// ---- incremental rendering ------------------------------------------------

interface BlockState {
  hasBlankLineAfter: boolean;
  output: ReactNode[];
  startLine: number;
  startOffset: number;
}

export interface IncrementalState {
  blocks: BlockState[];
  cacheKey: unknown;
  enabled: boolean;
  fallbackReason?: "disabled" | "document-context";
  outputs: ReactNode[][];
  source: string;
  stableBlockCount: number;
}

/** The identity of a config is the cache key: a new config drops the cache. */
interface IncrementalConfig {
  enabled: boolean;
  parse: ParseOptions;
  render: (nodes: HastNode[]) => ReactNode[];
}

const wholeDocument = (
  source: string,
  config: IncrementalConfig,
  reason: "disabled" | "document-context"
): IncrementalState => {
  const nodes: HastNode[] = [];

  for (const block of parseMarkdownBlocks(source, config.parse)) {
    if (nodes.length > 0) {
      nodes.push({ type: "text", value: "\n" });
    }

    nodes.push(block.node);
  }

  const output = config.render(nodes);

  return {
    blocks: [
      {
        hasBlankLineAfter: false,
        output,
        startLine: 1,
        startOffset: 0,
      },
    ],
    cacheKey: config,
    enabled: config.enabled,
    fallbackReason: reason,
    outputs: [output],
    source,
    stableBlockCount: 0,
  };
};

/** Parses only from the first unstable block when text is appended. */
export const advanceIncremental = (
  previous: IncrementalState | undefined,
  source: string,
  config: IncrementalConfig
): IncrementalState => {
  const sameConfig =
    previous?.cacheKey === config && previous?.enabled === config.enabled;

  if (previous && sameConfig && previous.source === source) {
    return previous;
  }

  if (!config.enabled) {
    return wholeDocument(source, config, "disabled");
  }

  if (
    source.includes("]:") ||
    source.includes("[^") ||
    source.includes("\uFEFF")
  ) {
    return wholeDocument(source, config, "document-context");
  }

  const canResume =
    sameConfig &&
    previous !== undefined &&
    !previous.fallbackReason &&
    source.length > previous.source.length &&
    source.startsWith(previous.source);

  const stable = canResume
    ? previous.blocks.slice(0, previous.stableBlockCount)
    : [];

  const unstable = canResume
    ? previous.blocks[previous.stableBlockCount]
    : undefined;

  const offset = unstable?.startOffset ?? 0;
  const firstLine = unstable?.startLine ?? 1;
  const parsed = parseMarkdownBlocks(source.slice(offset), config.parse);
  const blocks: BlockState[] = [...stable];

  for (const block of parsed) {
    blocks.push({
      hasBlankLineAfter: block.hasBlankLineAfter,
      output: config.render([block.node]),
      startLine: firstLine - 1 + block.startLine,
      startOffset: offset + block.startOffset,
    });
  }

  let stableBlockCount = 0;

  for (let index = blocks.length - 3; index >= 0; index -= 1) {
    if (blocks[index]?.hasBlankLineAfter) {
      stableBlockCount = index + 1;
      break;
    }
  }

  return {
    blocks,
    cacheKey: config,
    enabled: config.enabled,
    outputs: blocks.map((block) => block.output),
    source,
    stableBlockCount,
  };
};

const KEY_SUFFIX = /-\d+$/;

interface Joined {
  children: ReactNode[];
  normalized: Map<ReactElement, ReactElement>;
  state: IncrementalState;
}

/** Renders `source` block by block with stable element keys. */
export const useIncrementalBlocks = (
  source: string,
  config: IncrementalConfig
): ReactNode[] => {
  const previous = useRef<Joined | undefined>(undefined);

  const joined = useMemo<Joined>(() => {
    const before = previous.current;
    const state = advanceIncremental(before?.state, source, config);
    const children: ReactNode[] = [];
    const counts = new Map<string, number>();
    const normalized = new Map<ReactElement, ReactElement>();
    state.outputs.forEach((output, index) => {
      if (index > 0) {
        children.push("\n");
      }

      for (const child of output) {
        if (!isValidElement(child)) {
          children.push(child);
          continue;
        }

        const base = child.key?.replace(KEY_SUFFIX, "") ?? "element";
        const seen = counts.get(base) ?? 0;
        counts.set(base, seen + 1);
        const key = `${base}-${seen}`;

        if (child.key === key) {
          children.push(child);
          continue;
        }

        const cached = before?.normalized.get(child);

        const next =
          cached?.key === key ? cached : cloneElement(child, { key });

        normalized.set(child, next);
        children.push(next);
      }
    });

    return { children, normalized, state };
  }, [source, config]);

  useLayoutEffect(() => {
    previous.current = joined;
  }, [joined]);

  return joined.children;
};

"use client";

/* oxlint-disable anti-slop/no-array-filter-map -- Stylistic. */
/* oxlint-disable anti-slop/no-runtime-typeof -- A value may be a string or a list, or a value or a function, as in the components. */
/* oxlint-disable anti-slop/require-safety-comment-for-type-assertion, typescript/no-unsafe-type-assertion -- SAFETY: custom properties in style objects, children props read after an element check, and regex matches checked before use. */
/* oxlint-disable eslint/complexity -- The parsers are single-pass state machines that follow the reference algorithms branch for branch. */
/* oxlint-disable node/callback-return, promise/prefer-await-to-callbacks -- The frame helper calls the caller's callback. */
/* oxlint-disable react/no-react-children -- The renderer reads and maps text children. */
/* oxlint-disable react/refs -- The component keeps the latest props in refs during render so timers read current values. */
/* oxlint-disable react/set-state-in-effect -- The group child reconciles its keyed children in a layout effect. */
/* oxlint-disable typescript/consistent-return -- Effects and ref callbacks return a cleanup only when they registered something. */
/* oxlint-disable typescript/strict-boolean-expressions -- Branches test optional flags, regex groups and empty strings by truthiness, as react-markdown and the component do. */
/* oxlint-disable typescript/switch-exhaustiveness-check -- The reducer and decoration switches end in a default that returns the idle state. */

import { cn } from "@/lib/utils";
import {
  Children,
  isValidElement,
  useCallback,
  useEffect,
  useLayoutEffect,
  useReducer,
  useRef,
  useState,
} from "react";
import type {
  CSSProperties,
  ElementType,
  ReactElement,
  ReactNode,
} from "react";

/**
 * A keyed presence transition. A keyed child
 * that leaves stays mounted until its exit duration passes; a child that
 * arrives enters on the second frame after it mounts.
 */

const DEFAULT_ENTER_DURATION = 480;
const DEFAULT_EXIT_DURATION = 320;
const DEFAULT_PLAIN_ENTER_DURATION = 420;
const DEFAULT_PLAIN_EXIT_DURATION = 220;
const FRAMES_BEFORE_ACTIVE = 2;

/** Runs `callback` after `frames` animation frames. */
const afterFrames = (callback: () => void, frames = FRAMES_BEFORE_ACTIVE) => {
  const viaTimeout = () => {
    const id = setTimeout(callback, 0);

    return () => {
      clearTimeout(id);
    };
  };

  if (
    typeof window.requestAnimationFrame !== "function" ||
    document.visibilityState === "hidden"
  ) {
    return viaTimeout();
  }

  let remaining = frames;
  let handle = 0;

  const tick = () => {
    remaining -= 1;

    if (remaining === 0) {
      callback();
    } else {
      handle = window.requestAnimationFrame(tick);
    }
  };

  handle = window.requestAnimationFrame(tick);

  return () => {
    if (typeof window.cancelAnimationFrame === "function") {
      window.cancelAnimationFrame(handle);
    }
  };
};

/** The raw prefers-reduced-motion query. */
const prefersReducedMotion = (): boolean =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

interface PhaseState {
  enter: boolean;
  enterActive: boolean;
  exit: boolean;
  exitActive: boolean;
  interrupted: boolean;
}

type PhaseAction =
  | { type: "enter-before" }
  | { type: "enter-active" }
  | { type: "exit-before" }
  | { type: "exit-active" }
  | { type: "done" };

const IDLE: PhaseState = {
  enter: false,
  enterActive: false,
  exit: false,
  exitActive: false,
  interrupted: false,
};

const phaseReducer = (state: PhaseState, action: PhaseAction): PhaseState => {
  switch (action.type) {
    case "enter-before": {
      return {
        enter: true,
        enterActive: false,
        exit: false,
        exitActive: false,
        interrupted: state.interrupted || state.exit,
      };
    }

    case "enter-active": {
      return {
        enter: true,
        enterActive: true,
        exit: false,
        exitActive: false,
        interrupted: false,
      };
    }

    case "exit-before": {
      return {
        enter: false,
        enterActive: false,
        exit: true,
        exitActive: false,
        interrupted: state.interrupted || state.enter,
      };
    }

    case "exit-active": {
      return {
        enter: false,
        enterActive: false,
        exit: true,
        exitActive: true,
        interrupted: false,
      };
    }

    default: {
      return IDLE;
    }
  }
};

const flag = (on: boolean) => (on ? "" : undefined);

interface ChildItem {
  element: ReactElement;
  preventMountTransition?: boolean;
  shouldRender: boolean;
}

interface TransitionChildProps {
  as: ElementType;
  children: ReactNode;
  className?: string;
  enterDuration: number;
  exitDuration: number;
  onExited: () => void;
  preventMountTransition?: boolean;
  shouldRender: boolean;
  style?: CSSProperties;
}

const TransitionChild = ({
  as: Tag,
  children,
  className,
  enterDuration,
  exitDuration,
  onExited,
  preventMountTransition,
  shouldRender,
  style,
}: TransitionChildProps) => {
  const [phase, dispatch] = useReducer(
    phaseReducer,
    undefined,
    (): PhaseState => ({ ...IDLE, enter: !preventMountTransition })
  );

  const mounted = useRef(false);
  const enterRef = useRef(enterDuration);
  enterRef.current = enterDuration;
  const exitRef = useRef(exitDuration);
  exitRef.current = exitDuration;
  const exitedRef = useRef(onExited);
  exitedRef.current = onExited;

  useLayoutEffect(() => {
    let timer: number | undefined;

    if (!shouldRender) {
      dispatch({ type: "exit-before" });

      const cancel = afterFrames(() => {
        dispatch({ type: "exit-active" });
        // oxlint-disable-next-line react/immutability -- local to this effect or callback, not render state; oxlint 1.91 misreports it
        timer = window.setTimeout(() => {
          exitedRef.current();
        }, exitRef.current);
      });

      return () => {
        cancel();

        if (timer !== undefined) {
          clearTimeout(timer);
        }
      };
    }

    if (preventMountTransition && !mounted.current) {
      mounted.current = true;

      return;
    }

    dispatch({ type: "enter-before" });

    const cancel = afterFrames(() => {
      dispatch({ type: "enter-active" });
      timer = window.setTimeout(() => {
        dispatch({ type: "done" });
      }, enterRef.current);
    });

    return () => {
      cancel();

      if (timer !== undefined) {
        clearTimeout(timer);
      }
    };
  }, [shouldRender, preventMountTransition]);

  useEffect(
    () => () => {
      mounted.current = false;
    },
    []
  );

  return (
    <Tag
      className={cn(className, "block")}
      data-entering={flag(phase.enter)}
      data-entering-active={flag(phase.enterActive)}
      data-exiting={flag(phase.exit)}
      data-exiting-active={flag(phase.exitActive)}
      data-interrupted={flag(phase.interrupted)}
      style={style}
    >
      {children}
    </Tag>
  );
};

const keyedChildren = (children: ReactNode): ReactElement[] => {
  const keyed: ReactElement[] = [];
  Children.forEach(children, (child) => {
    if (isValidElement(child) && child.key !== null) {
      keyed.push(child);
    } else if (child) {
      throw new Error("Give each TransitionGroup child its own React key");
    }
  });

  return keyed;
};

const mergeItems = (
  next: ReactElement[],
  previous: ChildItem[],
  insertMethod: "append" | "prepend"
): ChildItem[] => {
  const nextKeys = new Set(next.map((child) => child.key));
  const previousKeys = new Set(previous.map((item) => item.element.key));

  const added = next
    .filter((child) => !previousKeys.has(child.key))
    .map((element): ChildItem => ({ element, shouldRender: true }));

  const kept = previous.map((item): ChildItem => ({
    ...item,
    element:
      next.find((child) => child.key === item.element.key) ?? item.element,
    shouldRender: nextKeys.has(item.element.key),
  }));

  return insertMethod === "append" ? [...kept, ...added] : [...added, ...kept];
};

export interface TransitionGroupProps {
  as?: ElementType;
  children?: ReactNode;
  className?: string;
  /** Skips the transitions. Default: the reduced-motion query. */
  disableAnimations?: boolean;
  enterDuration?: number;
  exitDuration?: number;
  insertMethod?: "append" | "prepend";
  preventInitialTransition?: boolean;
  style?: CSSProperties;
}

export const TransitionGroup = ({
  as = "span",
  children,
  className,
  disableAnimations,
  enterDuration = 0,
  exitDuration = 0,
  insertMethod = "append",
  preventInitialTransition = true,
  style,
}: TransitionGroupProps) => {
  const [items, setItems] = useState<ChildItem[]>(() =>
    keyedChildren(children).map((element) => ({
      element,
      preventMountTransition: preventInitialTransition,
      shouldRender: true,
    }))
  );

  const Tag = as;

  useLayoutEffect(() => {
    setItems((previous) =>
      mergeItems(keyedChildren(children), previous, insertMethod)
    );
  }, [children, insertMethod]);

  const removeChild = useCallback((key: ReactElement["key"]) => {
    setItems((previous) => previous.filter((item) => item.element.key !== key));
  }, []);

  if (disableAnimations ?? prefersReducedMotion()) {
    return (
      <>
        {keyedChildren(children).map((element) => (
          <Tag className={className} key={element.key} style={style}>
            {element}
          </Tag>
        ))}
      </>
    );
  }

  const current = new Map(
    keyedChildren(children).map((element) => [element.key, element])
  );

  return (
    <>
      {items.map((item) => {
        const element = current.get(item.element.key) ?? item.element;

        return (
          <TransitionChild
            as={as}
            className={className}
            enterDuration={enterDuration}
            exitDuration={exitDuration}
            key={element.key}
            onExited={() => {
              removeChild(element.key);
            }}
            preventMountTransition={item.preventMountTransition}
            shouldRender={item.shouldRender}
            style={style}
          >
            {element}
          </TransitionChild>
        );
      })}
    </>
  );
};

export interface TransitionMotion {
  /** Milliseconds. */
  delay?: number;
  duration?: number;
  opacity?: number;
  scale?: number;
  timingFunction?: string;
}

export interface TransitionItemProps {
  as?: ElementType;
  children?: ReactNode;
  className?: string;
  enter?: TransitionMotion;
  exit?: TransitionMotion;
  forceCompositeLayer?: boolean;
  initial?: TransitionMotion;
  insertMethod?: "append" | "prepend";
  preventInitialTransition?: boolean;
  /** Where entering and leaving items sit. Default `absolute`. */
  transitionPosition?: "absolute" | "static";
}

/**
 * States exclude each other so Tailwind variant order cannot change the result.
 */
const ITEM_STATE_CLASSES = [
  // [data-entering]: the initial values, no transition yet.
  "[&[data-entering]:not([data-entering-active]):not([data-interrupted])]:opacity-(--ck-presence-initial-opacity) [&[data-entering]:not([data-entering-active]):not([data-interrupted])]:[filter:var(--ck-presence-initial-filter)] [&[data-entering]:not([data-entering-active]):not([data-interrupted])]:transform-(--ck-presence-initial-transform)",
  // [data-exiting]: the enter values, no transition yet.
  "[&[data-exiting]:not([data-exiting-active]):not([data-interrupted])]:opacity-(--ck-presence-enter-opacity) [&[data-exiting]:not([data-exiting-active]):not([data-interrupted])]:[filter:var(--ck-presence-enter-filter)] [&[data-exiting]:not([data-exiting-active]):not([data-interrupted])]:transform-(--ck-presence-enter-transform)",
  // [data-entering-active]: the enter values with the enter transition.
  "[&[data-entering-active]]:opacity-(--ck-presence-enter-opacity) [&[data-entering-active]]:[filter:var(--ck-presence-enter-filter)] [&[data-entering-active]]:transform-(--ck-presence-enter-transform) [&[data-entering-active]]:[transition:opacity_var(--ck-presence-enter-duration)_var(--ck-presence-enter-timing-function)_var(--ck-presence-enter-delay),transform_var(--ck-presence-enter-duration)_var(--ck-presence-enter-timing-function)_var(--ck-presence-enter-delay),filter_var(--ck-presence-enter-duration)_var(--ck-presence-enter-timing-function)_var(--ck-presence-enter-delay)]",
  // [data-entering][data-interrupted]: the same, without the delay.
  "[&[data-entering][data-interrupted]]:opacity-(--ck-presence-enter-opacity) [&[data-entering][data-interrupted]]:[filter:var(--ck-presence-enter-filter)] [&[data-entering][data-interrupted]]:transform-(--ck-presence-enter-transform) [&[data-entering][data-interrupted]]:[transition:opacity_var(--ck-presence-enter-duration)_var(--ck-presence-enter-timing-function)_0s,transform_var(--ck-presence-enter-duration)_var(--ck-presence-enter-timing-function)_0s,filter_var(--ck-presence-enter-duration)_var(--ck-presence-enter-timing-function)_0s]",
  // [data-exiting-active]: the exit values with the exit transition.
  "[&[data-exiting-active]]:opacity-(--ck-presence-exit-opacity) [&[data-exiting-active]]:[filter:var(--ck-presence-exit-filter)] [&[data-exiting-active]]:transform-(--ck-presence-exit-transform) [&[data-exiting-active]]:[transition:opacity_var(--ck-presence-exit-duration)_var(--ck-presence-exit-timing-function)_var(--ck-presence-exit-delay),transform_var(--ck-presence-exit-duration)_var(--ck-presence-exit-timing-function)_var(--ck-presence-exit-delay),filter_var(--ck-presence-exit-duration)_var(--ck-presence-exit-timing-function)_var(--ck-presence-exit-delay)]",
  // [data-exiting][data-interrupted]: the same, without the delay.
  "[&[data-exiting][data-interrupted]]:opacity-(--ck-presence-exit-opacity) [&[data-exiting][data-interrupted]]:[filter:var(--ck-presence-exit-filter)] [&[data-exiting][data-interrupted]]:transform-(--ck-presence-exit-transform) [&[data-exiting][data-interrupted]]:[transition:opacity_var(--ck-presence-exit-duration)_var(--ck-presence-exit-timing-function)_0s,transform_var(--ck-presence-exit-duration)_var(--ck-presence-exit-timing-function)_0s,filter_var(--ck-presence-exit-duration)_var(--ck-presence-exit-timing-function)_0s]",
].join(" ");

// [data-ck-transition-position=absolute] rules: a leaving item, and an entering
// item that follows a sibling which is not leaving, stack over the others.
const ITEM_ABSOLUTE_CLASSES =
  "data-exiting:absolute data-exiting:top-0 data-exiting:left-0 data-exiting:w-full [:not([data-exiting])+&[data-entering]]:absolute [:not([data-exiting])+&[data-entering]]:top-0 [:not([data-exiting])+&[data-entering]]:left-0 [:not([data-exiting])+&[data-entering]]:w-full";

const transformOf = (motion?: TransitionMotion): string =>
  motion?.scale === undefined ? "none" : `scale(${motion.scale})`;

/**
 * Keyed presence with the enter, exit and initial motion held in
 * `--ck-presence-*` custom properties. The states use
 * Tailwind data-attribute variants on the group child.
 */
export const TransitionItem = ({
  as = "span",
  children,
  className,
  enter,
  exit,
  forceCompositeLayer,
  initial,
  insertMethod,
  preventInitialTransition,
  transitionPosition = "absolute",
}: TransitionItemProps) => {
  const initialTransform = transformOf(initial);
  const enterTransform = transformOf(enter);
  const exitTransform = transformOf(exit);

  const moving = [initialTransform, exitTransform, enterTransform].some(
    (value) => value !== "none"
  );

  const enterDuration =
    enter?.duration ??
    (moving ? DEFAULT_ENTER_DURATION : DEFAULT_PLAIN_ENTER_DURATION);

  const exitDuration =
    exit?.duration ??
    (moving ? DEFAULT_EXIT_DURATION : DEFAULT_PLAIN_EXIT_DURATION);

  const enterTiming =
    enter?.timingFunction ?? (moving ? "var(--ck-curve-enter)" : "ease");

  const exitTiming =
    exit?.timingFunction ?? (moving ? "var(--ck-curve-exit)" : "ease");

  const variables = {
    "--ck-presence-enter-delay": `${enter?.delay ?? 0}ms`,
    "--ck-presence-enter-duration": `${enterDuration}ms`,
    "--ck-presence-enter-filter": "none",
    "--ck-presence-enter-opacity": String(enter?.opacity ?? 1),
    "--ck-presence-enter-timing-function": enterTiming,
    "--ck-presence-enter-transform": enterTransform,
    "--ck-presence-exit-delay": `${exit?.delay ?? 0}ms`,
    "--ck-presence-exit-duration": `${exitDuration}ms`,
    "--ck-presence-exit-filter": "none",
    "--ck-presence-exit-opacity": String(exit?.opacity ?? 0),
    "--ck-presence-exit-timing-function": exitTiming,
    "--ck-presence-exit-transform": exitTransform,
    "--ck-presence-initial-filter": "none",
    "--ck-presence-initial-opacity": String(
      initial?.opacity ?? exit?.opacity ?? 0
    ),
    "--ck-presence-initial-transform":
      initialTransform === "none" ? exitTransform : initialTransform,
    "--ck-presence-will-change": forceCompositeLayer
      ? "transform, opacity"
      : "auto",
  } as CSSProperties;

  const Tag = as;

  return (
    <Tag
      className={cn(
        "block",
        transitionPosition === "absolute" && "relative",
        className
      )}
      data-ck-transition-position={transitionPosition}
      style={variables}
    >
      <TransitionGroup
        as={as}
        className={cn(
          "will-change-(--ck-presence-will-change)",
          ITEM_STATE_CLASSES,
          transitionPosition === "absolute" && ITEM_ABSOLUTE_CLASSES
        )}
        enterDuration={
          enter?.delay === undefined
            ? enterDuration
            : enter.delay + enterDuration
        }
        exitDuration={(exit?.delay ?? 0) + exitDuration}
        insertMethod={insertMethod}
        preventInitialTransition={preventInitialTransition}
      >
        {children}
      </TransitionGroup>
    </Tag>
  );
};

"use client";

import { CopyActionButton } from "@/components/markdown/copy-action-button";
/* oxlint-disable shadcn/no-arbitrary-values -- The component sizes the block text with the chat font size (--ui-message-text-size); no theme token matches it. */
import { Button } from "@/components/ui/button";
import { WritingBlockSurface } from "@/components/ui/card";
import { copyMarkdownText } from "@/components/ui/markdown";
import { MessageCirclePlus as LucideMessageCirclePlus } from "lucide-react";
import { useRef } from "react";
import type { ComponentProps } from "react";

/** (16px chat bubble), the glyph of the add to chat button. */
const AddToChatIcon = (props: ComponentProps<"svg">) => (
  <LucideMessageCirclePlus
    aria-hidden="true"
    height={16}
    width={16}
    {...props}
    strokeWidth={1.5}
  />
);

export interface MarkdownWritingBlockProps {
  className?: string;
  /** The block text, shown as written. */
  content: string;
  /** Gets the trimmed text and a range over the block. Without it the button is not shown. */
  onAddSelectedTextToChat?: (text: string, range: Range) => void;
  /** The copy button. Default `true`. */
  showCopyButton?: boolean;
}

/**
 * The
 * block text on the writing block surface, under a bar with the add to chat
 * button on the left and the copy button on the right.
 */
export const MarkdownWritingBlock = ({
  className,
  content,
  onAddSelectedTextToChat,
  showCopyButton = true,
}: MarkdownWritingBlockProps) => {
  const textRef = useRef<HTMLDivElement>(null);

  const addToChat = () => {
    const text = content.trim();
    const element = textRef.current;

    if (text.length === 0 || element === null) {
      return;
    }

    const range = element.ownerDocument.createRange();

    range.selectNodeContents(element);
    onAddSelectedTextToChat?.(text, range);
  };

  return (
    <WritingBlockSurface
      className={className}
      data-ck-markdown-copy="code-block"
    >
      <div
        className="flex items-center px-2 pt-2 pb-2 font-sans text-sm text-(color:--ck-palette-ink-tertiary) select-none"
        data-ck-markdown-copy="exclude"
      >
        {onAddSelectedTextToChat ? (
          <Button
            color="outline"
            onClick={addToChat}
            onMouseDown={(event) => {
              event.preventDefault();
            }}
            size="composer"
          >
            <AddToChatIcon aria-hidden="true" className="size-3.5" />
            Add to chat
          </Button>
        ) : null}
        {showCopyButton ? (
          <span className="ms-auto">
            <CopyActionButton
              label="Copy"
              onCopy={async () => await copyMarkdownText(content)}
              variant="toolbar"
            />
          </span>
        ) : null}
      </div>
      <div
        className="overflow-auto px-4 pt-2 pb-4 text-[length:var(--ui-message-text-size,13px)] whitespace-pre-wrap [unicode-bidi:plaintext]"
